INSERT INTO _fields_wd1_plan (site_id, column_name, old_value, new_value, change_key, reason, evidence) VALUES
    ('62c6ca1d-d37b-45b2-a773-15ce8bf69ea1'::uuid, 'period_name', '1 - 500 AD', '500 BC - 1 AD', 'fields-wd1-2026-09-26b-s005:62c6ca1d-d37b-45b2-a773-15ce8bf69ea1:period_name', 'fields-wd1-2026-09-26b-s005 (wd1-derive-period-name): period_start -342 (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-342) = ''500 BC - 1 AD''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('62c6ca1d-d37b-45b2-a773-15ce8bf69ea1'::uuid, 'period_start', '1', '-342', 'fields-wd1-2026-09-26b-s005:62c6ca1d-d37b-45b2-a773-15ce8bf69ea1:period_start', 'fields-wd1-2026-09-26b-s005 (wd1-replace): ''1'' -> ''-342''', '[{"source": "https://en.wikipedia.org/wiki/Plovdiv", "url": "https://en.wikipedia.org/wiki/Plovdiv", "quote": "settling there both Thracians and 2,000 Macedonians (Greeks) in 342 BC.", "outcome": "found"}, {"source": "https://www.livius.org/articles/place/philippopolis-plovdiv/", "url": "https://www.livius.org/articles/place/philippopolis-plovdiv/", "quote": "Philippopolis was founded by and named after king Philip II of Macedonia in 342/341 BCE, after he had captured a fortified settlement of the Thracian Bessi on the plain of the Upper Hebros (modern Maritsa).", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0014)", "decision": "replace", "status": "MISSING", "reasoning": "Wikipedia and Livius both date the foundation of Philippopolis as a polis by Philip II to 342 BC, on a Thracian settlement he captured; the start lies in the 500 BC - 1 AD bucket, not in the stored Roman 1 - 500 AD one.", "value_page": null}]'::jsonb),
    ('62c6ca1d-d37b-45b2-a773-15ce8bf69ea1'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Philippopolis_(Thrace)', 'https://bg.wikipedia.org/wiki/%D0%A4%D0%B8%D0%BB%D0%B8%D0%BF%D0%BE%D0%BF%D0%BE%D0%BB', 'fields-wd1-2026-09-26b-s005:62c6ca1d-d37b-45b2-a773-15ce8bf69ea1:source_url', 'fields-wd1-2026-09-26b-s005 (wd1-replace): ''https://en.wikipedia.org/wiki/Philippopolis_(Thrace)'' -> ''https://bg.wikipedia.org/wiki/%D0%A4%D0%B8%D0%BB%D0%B8%D0%BF%D0%BE%D0%BF%D0%BE%D0%BB''', '[{"source": "https://bg.wikipedia.org/wiki/%D0%A4%D0%B8%D0%BB%D0%B8%D0%BF%D0%BE%D0%BF%D0%BE%D0%BB", "url": "https://bg.wikipedia.org/wiki/%D0%A4%D0%B8%D0%BB%D0%B8%D0%BF%D0%BE%D0%BF%D0%BE%D0%BB", "quote": "Филипопол е едно от древните имена на днешния Пловдив, което е било най-разпространено през вековете.", "outcome": "found"}, {"source": "https://www.livius.org/articles/place/philippopolis-plovdiv/", "url": "https://www.livius.org/articles/place/philippopolis-plovdiv/", "quote": "Philippopolis was founded by and named after king Philip II of Macedonia in 342/341 BCE, after he had captured a fortified settlement of the Thracian Bessi on the plain of the Upper Hebros (modern Maritsa).", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0014)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored English URL only redirects to the article on the modern city of Plovdiv; English Wikipedia has no article on the ancient city, while the Bulgarian article Филипопол (the Wikidata sitelink of the ancient-city item) is about ancient Philippopolis itself, which Livius also describes.", "value_page": {"lang": "bg", "problem": null, "resolved_title": "Филипопол", "unreadable": false, "wikibase_item": "Q27047924"}}]'::jsonb),
    ('62c8bf00-3a7e-46e6-81ac-2c6fc92af03f'::uuid, 'geom', '0101000020E61000001C11DDC83F276040F2EA5AE308E54140', 'SRID=4326;POINT(129.225556 35.768056)', 'fields-wd1-2026-09-26b-s005:62c8bf00-3a7e-46e6-81ac-2c6fc92af03f:geom', 'fields-wd1-2026-09-26b-s005 (wd1-point): 35.78933374347061, 129.2265362088882 -> 35.768056, 129.225556', '[{"source": "https://en.wikipedia.org/wiki/Namsan_(Gyeongju)", "url": "https://en.wikipedia.org/wiki/Namsan_(Gyeongju)", "quote": "35.76806°N 129.22556°E", "outcome": "found"}, {"source": "https://www.openstreetmap.org/node/5376919634", "url": "https://www.openstreetmap.org/node/5376919634", "quote": "35.7675600, 129.2252900", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0128)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored point is a placeholder shared with the other Gyeongju belts (the coordinates of the whole World Heritage property). The Mount Namsan Belt is the mountain Namsan itself; Wikipedia gives the mountain at 35.76806 N, 129.22556 E, and the OpenStreetMap node of its summit Gowibong lies 60 m from that point, 2.4 km from the stored point.", "value_page": null}]'::jsonb),
    ('62c8bf00-3a7e-46e6-81ac-2c6fc92af03f'::uuid, 'lat', '35.78933374347061', '35.768056', 'fields-wd1-2026-09-26b-s005:62c8bf00-3a7e-46e6-81ac-2c6fc92af03f:lat', 'fields-wd1-2026-09-26b-s005 (wd1-replace): 35.78933374347061, 129.2265362088882 -> 35.768056, 129.225556', '[{"source": "https://en.wikipedia.org/wiki/Namsan_(Gyeongju)", "url": "https://en.wikipedia.org/wiki/Namsan_(Gyeongju)", "quote": "35.76806°N 129.22556°E", "outcome": "found"}, {"source": "https://www.openstreetmap.org/node/5376919634", "url": "https://www.openstreetmap.org/node/5376919634", "quote": "35.7675600, 129.2252900", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0128)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored point is a placeholder shared with the other Gyeongju belts (the coordinates of the whole World Heritage property). The Mount Namsan Belt is the mountain Namsan itself; Wikipedia gives the mountain at 35.76806 N, 129.22556 E, and the OpenStreetMap node of its summit Gowibong lies 60 m from that point, 2.4 km from the stored point.", "value_page": null}]'::jsonb),
    ('62c8bf00-3a7e-46e6-81ac-2c6fc92af03f'::uuid, 'lon', '129.2265362088882', '129.225556', 'fields-wd1-2026-09-26b-s005:62c8bf00-3a7e-46e6-81ac-2c6fc92af03f:lon', 'fields-wd1-2026-09-26b-s005 (wd1-replace): 35.78933374347061, 129.2265362088882 -> 35.768056, 129.225556', '[{"source": "https://en.wikipedia.org/wiki/Namsan_(Gyeongju)", "url": "https://en.wikipedia.org/wiki/Namsan_(Gyeongju)", "quote": "35.76806°N 129.22556°E", "outcome": "found"}, {"source": "https://www.openstreetmap.org/node/5376919634", "url": "https://www.openstreetmap.org/node/5376919634", "quote": "35.7675600, 129.2252900", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0128)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored point is a placeholder shared with the other Gyeongju belts (the coordinates of the whole World Heritage property). The Mount Namsan Belt is the mountain Namsan itself; Wikipedia gives the mountain at 35.76806 N, 129.22556 E, and the OpenStreetMap node of its summit Gowibong lies 60 m from that point, 2.4 km from the stored point.", "value_page": null}]'::jsonb),
    ('62c8bf00-3a7e-46e6-81ac-2c6fc92af03f'::uuid, 'period_name', '1 - 500 AD', NULL, 'fields-wd1-2026-09-26b-s005:62c8bf00-3a7e-46e6-81ac-2c6fc92af03f:period_name', 'fields-wd1-2026-09-26b-s005 (wd1-derive-period-name): period_start None (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('62c8bf00-3a7e-46e6-81ac-2c6fc92af03f'::uuid, 'period_start', '1', NULL, 'fields-wd1-2026-09-26b-s005:62c8bf00-3a7e-46e6-81ac-2c6fc92af03f:period_start', 'fields-wd1-2026-09-26b-s005 (wd1-clear): ''1'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0128)", "decision": "clear", "status": "MISSING", "reasoning": "The belt gathers remains of many dates on the mountain - the legendary birthplace of the Silla founder, royal tombs of attributed kings, the Namsan fortress of 591 and Buddhist temples, statues and pagodas mostly of the 7th to 10th centuries. No source dates the start of the site''s history as a whole, and the stored value 1 is a placeholder, so the field is emptied.", "value_page": null}]'::jsonb),
    ('62c8bf00-3a7e-46e6-81ac-2c6fc92af03f'::uuid, 'site_type', 'Rock relief/carving', 'Sacred site', 'fields-wd1-2026-09-26b-s005:62c8bf00-3a7e-46e6-81ac-2c6fc92af03f:site_type', 'fields-wd1-2026-09-26b-s005 (wd1-replace): ''Rock relief/carving'' -> ''Sacred site''', '[{"source": "https://english.khs.go.kr/chaen/search/selectGeneralSearchDetail.do?mn=EN_02_02&sCcebKdcd=13&ccebAsno=0003110000000&sCcebCtcd=37", "url": "https://english.khs.go.kr/chaen/search/selectGeneralSearchDetail.do?mn=EN_02_02&sCcebKdcd=13&ccebAsno=0003110000000&sCcebCtcd=37", "quote": "Namsan Mountain in Gyeongju is also called Geumosan Mountain and has been regarded as the most sacred place in the millennium-long history of Silla.", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Gyeongju_Historic_Areas", "url": "https://en.wikipedia.org/wiki/Gyeongju_Historic_Areas", "quote": "The Mount Namsan Belt is based around the holy mountain", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0128)", "decision": "replace", "status": "MISSING", "reasoning": "The heritage register calls Namsan the most sacred place of Silla and Wikipedia describes the belt as based around the holy mountain Namsan, with temple ruins, statues, pagodas, tombs and a fortress besides its rock reliefs. Sacred site names what the whole belt is; Rock relief/carving covers only one class of its remains.", "value_page": null}]'::jsonb),
    ('62c8bf00-3a7e-46e6-81ac-2c6fc92af03f'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Gyeongju_Historic_Areas', 'https://en.wikipedia.org/wiki/Namsan_(Gyeongju)', 'fields-wd1-2026-09-26b-s005:62c8bf00-3a7e-46e6-81ac-2c6fc92af03f:source_url', 'fields-wd1-2026-09-26b-s005 (wd1-replace): ''https://en.wikipedia.org/wiki/Gyeongju_Historic_Areas'' -> ''https://en.wikipedia.org/wiki/Namsan_(Gyeongju)''', '[{"source": "https://en.wikipedia.org/wiki/Namsan_(Gyeongju)", "url": "https://en.wikipedia.org/wiki/Namsan_(Gyeongju)", "quote": "Namsan is home to many historic and cultural remains, and is now part of the historic area around Gyeongju that was added to the UNESCO list of World Heritage in 2000.", "outcome": "found"}, {"source": "https://english.khs.go.kr/chaen/search/selectGeneralSearchDetail.do?mn=EN_02_02&sCcebKdcd=13&ccebAsno=0003110000000&sCcebCtcd=37", "url": "https://english.khs.go.kr/chaen/search/selectGeneralSearchDetail.do?mn=EN_02_02&sCcebKdcd=13&ccebAsno=0003110000000&sCcebCtcd=37", "quote": "Namsan Mountain in Gyeongju is also called Geumosan Mountain and has been regarded as the most sacred place in the millennium-long history of Silla.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0128)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored page is the article on the whole World Heritage property (Q495241). The Mount Namsan Belt is the mountain Namsan with its remains; the English Wikipedia article on Namsan (Gyeongju) covers that heritage area (it lists the Historic Site ''Archaeological Area of Namsan Mountain, Gyeongju'' and the World Heritage listing), and the Korea Heritage Service register describes the same area.", "value_page": {"lang": "en", "problem": null, "resolved_title": "Namsan (Gyeongju)", "unreadable": false, "wikibase_item": "Q489229"}}]'::jsonb),
    ('62c99642-3f6b-4122-a872-6c5f452aa35f'::uuid, 'period_name', '1 - 500 AD', '1000 - 1500 AD', 'fields-wd1-2026-09-26b-s005:62c99642-3f6b-4122-a872-6c5f452aa35f:period_name', 'fields-wd1-2026-09-26b-s005 (wd1-derive-period-name): period_start 1323 (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(1323) = ''1000 - 1500 AD''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('62c99642-3f6b-4122-a872-6c5f452aa35f'::uuid, 'period_start', '1', '1323', 'fields-wd1-2026-09-26b-s005:62c99642-3f6b-4122-a872-6c5f452aa35f:period_start', 'fields-wd1-2026-09-26b-s005 (wd1-replace): ''1'' -> ''1323''', '[{"source": "https://journals.openedition.org/bifea/4936", "url": "https://journals.openedition.org/bifea/4936", "quote": "La fecha corresponde a los años calibrados 1323-1346 ó 1390-1418", "outcome": "found"}, {"source": "https://journals.openedition.org/bifea/4936", "url": "https://journals.openedition.org/bifea/4936", "quote": "En base a este resultado, la fecha más probable de construcción de la chullpa es el siglo XIV.", "outcome": "found"}, {"source": "https://es.wikipedia.org/wiki/Se%C3%B1or%C3%ADos_aimaras", "url": "https://es.wikipedia.org/wiki/Se%C3%B1or%C3%ADos_aimaras", "quote": "fechada entre el 1323 y 1428, antes de la conquista inca de los pacajes.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0012)", "decision": "replace", "status": "MISSING", "reasoning": "Kesseli and Pärssinen''s radiocarbon date of a Jachaphasa chullpa gives calibrated 1323-1346 or 1390-1418, construction most probably in the 14th century, and Spanish Wikipedia dates the Fortaleza de Jachaphasa to 1323-1428; the Pacajes-period fortress and necropolis thus begin in the 1000-1500 AD bucket, not in 1-500 AD.", "value_page": null}]'::jsonb),
    ('62f21f04-c668-474e-8548-69bbdbc35620'::uuid, 'site_type', 'Megalithic structures', 'Temple', 'fields-wd1-2026-09-26b-s005:62f21f04-c668-474e-8548-69bbdbc35620:site_type', 'fields-wd1-2026-09-26b-s005 (wd1-replace): ''Megalithic structures'' -> ''Temple''', '[{"source": "https://perseus-aa.github.io/items/aa_300.html", "url": "https://perseus-aa.github.io/items/aa_300.html", "quote": "Small temple-like building; on the north side of the Sanctuary of Zeus (Altis), the 11th treasury from the west, and 2nd from the east on the Treasury Terrace.", "outcome": "found"}, {"source": "https://www.wikidata.org/wiki/Q96392534", "url": "https://www.wikidata.org/wiki/Q96392534", "quote": "small ruined temple that once held dedications", "outcome": "found"}, {"source": "http://odysseus.culture.gr/h/2/eh251.jsp?obj_id=5845", "url": "http://odysseus.culture.gr/h/2/eh251.jsp?obj_id=5845", "quote": "The treasuries were small temple-shaped buildings erected by various Greek cities for storing their precious offerings to Zeus.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0068)", "decision": "replace", "status": "CONFLICT", "reasoning": "The site is a Greek treasury: a small temple-form building in the sanctuary of Zeus that held Megara''s votive offerings (Perseus, Wikidata, Greek Ministry of Culture); nothing megalithic is described. With no treasury type among the canonical values, Temple is the most specific type that holds.", "value_page": null}]'::jsonb),
    ('63bb1b7d-6a64-43d9-8459-1d9606932658'::uuid, 'period_name', '1500 - 500 BC', NULL, 'fields-wd1-2026-09-26b-s005:63bb1b7d-6a64-43d9-8459-1d9606932658:period_name', 'fields-wd1-2026-09-26b-s005 (wd1-derive-period-name): period_start None (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('63bb1b7d-6a64-43d9-8459-1d9606932658'::uuid, 'period_start', '-1000', NULL, 'fields-wd1-2026-09-26b-s005:63bb1b7d-6a64-43d9-8459-1d9606932658:period_start', 'fields-wd1-2026-09-26b-s005 (wd1-clear): ''-1000'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0043)", "decision": "clear", "status": "MISSING", "reasoning": "Every readable source (Megalithic Portal, Wikipedia''s Peppercombe article, Devon Perspectives) only calls it an Iron Age hillfort; none gives a year or century for its construction or first occupation, so no attested start can be sourced.", "value_page": null}]'::jsonb),
    ('63bb1b7d-6a64-43d9-8459-1d9606932658'::uuid, 'site_type', 'Fortress/citadel', 'Fort', 'fields-wd1-2026-09-26b-s005:63bb1b7d-6a64-43d9-8459-1d9606932658:site_type', 'fields-wd1-2026-09-26b-s005 (wd1-replace): ''Fortress/citadel'' -> ''Fort''', '[{"source": "https://en.wikipedia.org/wiki/Peppercombe", "url": "https://en.wikipedia.org/wiki/Peppercombe", "quote": "Peppercombe Castle is an Iron Age Hill fort situated on the cliffs immediately to the west of the valley.", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=7764", "url": "https://www.megalithic.co.uk/article.php?sid=7764", "quote": "Site Name: Peppercombe Castle Country: England County: Devon Type: Hillfort", "outcome": "found"}, {"source": "https://www.devonperspectives.co.uk/peppercombe.html", "url": "https://www.devonperspectives.co.uk/peppercombe.html", "quote": "The top of the near-perpendicular section of cliff in the photo above is the site of Peppercombe Castle. This was once an Iron Age promontory hillfort.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0043)", "decision": "replace", "status": "CONFLICT", "reasoning": "Wikipedia, the Megalithic Portal and Devon Perspectives all describe Peppercombe Castle as an Iron Age hill fort (a promontory hillfort), which the canonical type Fort holds more exactly than Fortress/citadel.", "value_page": null}]'::jsonb),
    ('63bb1b7d-6a64-43d9-8459-1d9606932658'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Peppercombe', 'https://www.megalithic.co.uk/article.php?sid=7764', 'fields-wd1-2026-09-26b-s005:63bb1b7d-6a64-43d9-8459-1d9606932658:source_url', 'fields-wd1-2026-09-26b-s005 (wd1-replace): ''https://en.wikipedia.org/wiki/Peppercombe'' -> ''https://www.megalithic.co.uk/article.php?sid=7764''', '[{"source": "https://www.megalithic.co.uk/article.php?sid=7764", "url": "https://www.megalithic.co.uk/article.php?sid=7764", "quote": "Site Name: Peppercombe Castle Country: England County: Devon Type: Hillfort", "outcome": "found"}, {"source": "https://www.devonperspectives.co.uk/peppercombe.html", "url": "https://www.devonperspectives.co.uk/peppercombe.html", "quote": "The top of the near-perpendicular section of cliff in the photo above is the site of Peppercombe Castle. This was once an Iron Age promontory hillfort.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0043)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored Wikipedia article is about the Peppercombe valley and gives the fort only a short section; the Megalithic Portal page is an entry about Peppercombe Castle itself and loads as plain HTML, and Devon Perspectives independently names the same hillfort.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
    ('63d4e2b3-4dad-438d-be14-34bd79cf9842'::uuid, 'site_type', 'Megalithic stones', 'City', 'fields-wd1-2026-09-26b-s005:63d4e2b3-4dad-438d-be14-34bd79cf9842:site_type', 'fields-wd1-2026-09-26b-s005 (wd1-replace): ''Megalithic stones'' -> ''City''', '[{"source": "https://en.wikipedia.org/wiki/Salona", "url": "https://en.wikipedia.org/wiki/Salona", "quote": "was an ancient city and the capital of the Roman province of Dalmatia", "outcome": "found"}, {"source": "https://visitsolin.com/about-solin/history/", "url": "https://visitsolin.com/about-solin/history/", "quote": "The remains of the ramparts, and objects of Greek origin found in and around Salona, point to the Greeks as the founders of this city.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0018)", "decision": "replace", "status": "CONFLICT", "reasoning": "Wikipedia describes Salona as an ancient city and capital of Roman Dalmatia, and the Solin tourist board''s history page calls it a city founded by Greeks; it is a city, not megalithic stones.", "value_page": null}]'::jsonb),
    ('64fe03e2-33c3-4836-b012-b3e50917fcf6'::uuid, 'site_type', 'City/town/settlement', 'Settlement', 'fields-wd1-2026-09-26b-s005:64fe03e2-33c3-4836-b012-b3e50917fcf6:site_type', 'fields-wd1-2026-09-26b-s005 (wd1-replace): ''City/town/settlement'' -> ''Settlement''', '[{"source": "https://topostext.org/place/370251XSal", "url": "https://topostext.org/place/370251XSal", "quote": "Σαλιαγκός - Saliagos, Neolithic settlement on the islet of Saliagos between Antiparos and Paros, Cyclades", "outcome": "found"}, {"source": "https://cyclades.culture.gov.gr/en/location/saliagos-a-small-islet-between-the-islands-of-paros-and-antiparos/", "url": "https://cyclades.culture.gov.gr/en/location/saliagos-a-small-islet-between-the-islands-of-paros-and-antiparos/", "quote": "The island was visited in 1959 by N. Zapheiropoulos, who identified the remains of a prehistoric settlement.", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Saliagos", "url": "https://en.wikipedia.org/wiki/Saliagos", "quote": "It is the first early farming site and one of the oldest settlements of the Cycladic culture.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0071)", "decision": "replace", "status": "CONFLICT", "reasoning": "ToposText, the Ephorate of Antiquities of the Cyclades and Wikipedia all describe the site as a Neolithic farming and fishing settlement of houses within a wall, not a town or city; the specific canonical type is Settlement.", "value_page": null}]'::jsonb),
    ('65881dcd-e524-404a-a931-3d69e7348c71'::uuid, 'site_type', 'Temple complex', 'Sanctuary', 'fields-wd1-2026-09-26b-s005:65881dcd-e524-404a-a931-3d69e7348c71:site_type', 'fields-wd1-2026-09-26b-s005 (wd1-replace): ''Temple complex'' -> ''Sanctuary''', '[{"source": "http://www.minoancrete.com/juktas.htm", "url": "http://www.minoancrete.com/juktas.htm", "quote": "The Juktas Peak Sanctuary, also known as Psili Korfi, is located 13 kilometres south-west of Knossos, from where the mountain peak can be seen.", "outcome": "found"}, {"source": "https://topostext.org/place/352251LIyt", "url": "https://topostext.org/place/352251LIyt", "quote": "Famous Minoan and late peak sanctuary above Archanes in Irakleio Crete", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Mount_Juktas", "url": "https://en.wikipedia.org/wiki/Mount_Juktas", "quote": "Mount Juktas is the site of one of the most important peak sanctuaries in the Minoan world, and probably the first of them.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0068)", "decision": "replace", "status": "CONFLICT", "reasoning": "Every source describes the site as a Minoan peak sanctuary - an open-air cult place with altar, chasm, terraces and rooms inside a temenos wall - not a temple complex; Sanctuary is the canonical type that holds.", "value_page": null}]'::jsonb),
    ('65881dcd-e524-404a-a931-3d69e7348c71'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Mount_Juktas', 'http://www.minoancrete.com/juktas.htm', 'fields-wd1-2026-09-26b-s005:65881dcd-e524-404a-a931-3d69e7348c71:source_url', 'fields-wd1-2026-09-26b-s005 (wd1-replace): ''https://en.wikipedia.org/wiki/Mount_Juktas'' -> ''http://www.minoancrete.com/juktas.htm''', '[{"source": "http://www.minoancrete.com/juktas.htm", "url": "http://www.minoancrete.com/juktas.htm", "quote": "The Juktas Peak Sanctuary, also known as Psili Korfi, is located 13 kilometres south-west of Knossos, from where the mountain peak can be seen.", "outcome": "found"}, {"source": "https://topostext.org/place/352251LIyt", "url": "https://topostext.org/place/352251LIyt", "quote": "Famous Minoan and late peak sanctuary above Archanes in Irakleio Crete", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0068)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored English article is about the mountain, and no Wikipedia article is the sanctuary''s own (the German one is about the summit Psili Korfi); Minoan Crete''s page is devoted to the Juktas peak sanctuary itself, which ToposText also records as a place of its own.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
    ('65936955-be6f-43cc-a306-fc879106f442'::uuid, 'site_type', 'Megalithic structures', 'Amphitheatre', 'fields-wd1-2026-09-26b-s005:65936955-be6f-43cc-a306-fc879106f442:site_type', 'fields-wd1-2026-09-26b-s005 (wd1-replace): ''Megalithic structures'' -> ''Amphitheatre''', '[{"source": "https://en.wikipedia.org/wiki/Tours_Amphitheatre", "url": "https://en.wikipedia.org/wiki/Tours_Amphitheatre", "quote": "is a Roman amphitheatre located in the historic city centre of", "outcome": "found"}, {"source": "https://www.mikoflohr.org/tour_des_fouilles/tour_des_fouilles_(12)_the_amphitheatre_of_tours/", "url": "https://www.mikoflohr.org/tour_des_fouilles/tour_des_fouilles_(12)_the_amphitheatre_of_tours/", "quote": "The amphitheatre, by the way, was one of the largest of Roman Gaul - only those at Metz and Trier appear to have been bigger.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0055)", "decision": "replace", "status": "CONFLICT", "reasoning": "Wikipedia and Miko Flohr''s archaeological note both describe the site at Tours as a Roman amphitheatre, not a megalithic structure; the canonical type is Amphitheatre.", "value_page": null}]'::jsonb),
    ('665a152b-5e67-4110-b58e-7f1bce3b739c'::uuid, 'period_name', '1 - 500 AD', NULL, 'fields-wd1-2026-09-26b-s005:665a152b-5e67-4110-b58e-7f1bce3b739c:period_name', 'fields-wd1-2026-09-26b-s005 (wd1-derive-period-name): period_start None (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('665a152b-5e67-4110-b58e-7f1bce3b739c'::uuid, 'period_start', '1', NULL, 'fields-wd1-2026-09-26b-s005:665a152b-5e67-4110-b58e-7f1bce3b739c:period_start', 'fields-wd1-2026-09-26b-s005 (wd1-clear): ''1'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0013)", "decision": "clear", "status": "MISSING", "reasoning": "The sources date the Rego Grande megaliths only in years before present: English and Portuguese Wikipedia say 500 to 2000 years old, and Revista Pesquisa FAPESP reports charcoal from the funerary pits showing occupation ''around one thousand years ago''. None gives a year or century, and they do not support the stored AD 1 bucket.", "value_page": null}]'::jsonb),
    ('665a152b-5e67-4110-b58e-7f1bce3b739c'::uuid, 'site_type', 'Megalithic stones', 'Stone circle', 'fields-wd1-2026-09-26b-s005:665a152b-5e67-4110-b58e-7f1bce3b739c:site_type', 'fields-wd1-2026-09-26b-s005 (wd1-replace): ''Megalithic stones'' -> ''Stone circle''', '[{"source": "https://en.wikipedia.org/wiki/Parque_Arqueol%C3%B3gico_do_Solst%C3%ADcio", "url": "https://en.wikipedia.org/wiki/Parque_Arqueol%C3%B3gico_do_Solst%C3%ADcio", "quote": "It contains a megalithic stone circle", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=24990", "url": "https://www.megalithic.co.uk/article.php?sid=24990", "quote": "Type: Stone Circle", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0013)", "decision": "replace", "status": "MISSING", "reasoning": "Both English Wikipedia and the Megalithic Portal describe the site as a stone circle of 127 granite blocks about 30 m across. Stone circle is more specific than the stored ''Megalithic stones''.", "value_page": null}]'::jsonb),
