    ('66ca3d59-0402-4261-97cb-c5e5be3faac7'::uuid, 'period_name', '1000 - 1500 AD', '1500 - 500 BC', 'fields-wd1-2026-09-26b-s005:66ca3d59-0402-4261-97cb-c5e5be3faac7:period_name', 'fields-wd1-2026-09-26b-s005 (wd1-derive-period-name): period_start -600 (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-600) = ''1500 - 500 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('66ca3d59-0402-4261-97cb-c5e5be3faac7'::uuid, 'period_start', '1400', '-600', 'fields-wd1-2026-09-26b-s005:66ca3d59-0402-4261-97cb-c5e5be3faac7:period_start', 'fields-wd1-2026-09-26b-s005 (wd1-replace): ''1400'' -> ''-600''', '[{"source": "https://docslib.org/doc/10971231/continuity-and-change-in-the-formative-period-of-the-cusichaca-valley-department-of-cuzco-peru", "url": "https://docslib.org/doc/10971231/continuity-and-change-in-the-formative-period-of-the-cusichaca-valley-department-of-cuzco-peru", "quote": "Excavation of well-stratified occupation deposits on the Huillca Raccay promontory in the Cusichaca Valley has revealed a sequence of activity dating from c 600 BC to AD 100.", "outcome": "found"}, {"source": "https://atom.aim25.com/index.php/the-cusichaca-trust-2", "url": "https://atom.aim25.com/index.php/the-cusichaca-trust-2", "quote": "Archaeological excavation at the Inca site of Huillca Raccay and at other sites around and above the junction of the Cusichaca and Urubamba rivers, revealed a sequence of distinct occupations from c.700 BC to the time of the Spanish conquest in the 1530s.", "outcome": "found"}, {"source": "WD1 decision (counted, round 1, wd1-r1-b0019)", "decision": "replace", "status": "MISSING", "reasoning": "The UCL thesis on the Cusichaca valley dates the stratified occupation of the Huillca Raccay promontory from c 600 BC, and the Cusichaca Trust archive catalogue independently dates the occupation sequence at Huillca Raccay and its neighbouring sites from c.700 BC; the Inca use (stored 1400) is a later phase, so the first occupation lies in the 1500-500 BC bucket and the attested start is c. 600 BC.", "value_page": null}]'::jsonb),
    ('6724235d-289c-411b-9b85-ac18229a0212'::uuid, 'period_name', '1500 - 500 BC', '1500+ AD', 'fields-wd1-2026-09-26b-s005:6724235d-289c-411b-9b85-ac18229a0212:period_name', 'fields-wd1-2026-09-26b-s005 (wd1-derive-period-name): period_start 1864 (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(1864) = ''1500+ AD''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('6724235d-289c-411b-9b85-ac18229a0212'::uuid, 'period_start', '-1500', '1864', 'fields-wd1-2026-09-26b-s005:6724235d-289c-411b-9b85-ac18229a0212:period_start', 'fields-wd1-2026-09-26b-s005 (wd1-replace): ''-1500'' -> ''1864''', '[{"source": "https://en.wikipedia.org/wiki/Brean_Down_Fort", "url": "https://en.wikipedia.org/wiki/Brean_Down_Fort", "quote": "with construction beginning in 1864 and completed in 1871.", "outcome": "found"}, {"source": "https://www.abandonedspaces.com/conflict/brean-down-fort-in-england.html", "url": "https://www.abandonedspaces.com/conflict/brean-down-fort-in-england.html", "quote": "Construction of Brean Down Fort started in 1864 and was finished in 1871.", "outcome": "found"}, {"source": "https://www.higgypop.com/urbex/brean-down-fort/", "url": "https://www.higgypop.com/urbex/brean-down-fort/", "quote": "The fort was built between 1864 and 1871 on the recommendations of the 1859 Royal Commission.", "outcome": "found"}, {"source": "WD1 decision (counted, round 1, wd1-r1-b0005)", "decision": "replace", "status": "MISSING", "reasoning": "Brean Down Fort is the Victorian Palmerston fort on the headland; three independent pages date the start of its construction to 1864 (completed 1871), which lies in the 1500+ AD bucket, not the stored 1500 - 500 BC bucket; the Bronze Age settlement named by Wikipedia is on the headland, and no readable source gives it a year.", "value_page": null}]'::jsonb),
    ('6726100a-71c5-44b2-9286-b176dd495a51'::uuid, 'period_name', '1 - 500 AD', '500 BC - 1 AD', 'fields-wd1-2026-09-26b-s005:6726100a-71c5-44b2-9286-b176dd495a51:period_name', 'fields-wd1-2026-09-26b-s005 (wd1-derive-period-name): period_start -300 (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-300) = ''500 BC - 1 AD''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('6726100a-71c5-44b2-9286-b176dd495a51'::uuid, 'period_start', '1', '-300', 'fields-wd1-2026-09-26b-s005:6726100a-71c5-44b2-9286-b176dd495a51:period_start', 'fields-wd1-2026-09-26b-s005 (wd1-replace): ''1'' -> ''-300''', '[{"source": "https://en.wikipedia.org/wiki/Arsameia", "url": "https://en.wikipedia.org/wiki/Arsameia", "quote": "The ancient town of Nymphaios was renamed Arsameia in the third century BCE by the Armenian king Arsames (255–225 BCE).", "outcome": "found"}, {"source": "https://www.livius.org/articles/place/arsameia/", "url": "https://www.livius.org/articles/place/arsameia/", "quote": "who had ruled in this part of Armenia in the third quarter of the third century BCE", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0141)", "decision": "replace", "status": "MISSING", "reasoning": "Wikipedia and Livius (after Antiochus I''s inscription at Site III) both attribute the founding of Arsameia on the Nymphaios to king Arsames in the third century BCE, so the securely attested start falls in the 3rd century BC (-300), not in the stored 1-500 AD bucket.", "value_page": null}]'::jsonb),
    ('6726100a-71c5-44b2-9286-b176dd495a51'::uuid, 'site_type', 'Temple complex', 'City', 'fields-wd1-2026-09-26b-s005:6726100a-71c5-44b2-9286-b176dd495a51:site_type', 'fields-wd1-2026-09-26b-s005 (wd1-replace): ''Temple complex'' -> ''City''', '[{"source": "https://en.wikipedia.org/wiki/Arsameia", "url": "https://en.wikipedia.org/wiki/Arsameia", "quote": "is an ancient city located in Old Kâhta (Eski Kâhta) in Kâhta district", "outcome": "found"}, {"source": "https://turkisharchaeonews.net/site/arsameia-nymphaios", "url": "https://turkisharchaeonews.net/site/arsameia-nymphaios", "quote": "The Kingdom of Commagene had three main cities: Samosata and two Arsameias.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0141)", "decision": "replace", "status": "CONFLICT", "reasoning": "Arsemia Ören Yeri is Arsameia on the Nymphaios, described by Wikipedia and Turkish Archaeological News as an ancient city and royal seat of Commagene, with the hierothesion of Mithridates I as one part of it; no temple complex is attested there, so City fits the site as a whole.", "value_page": null}]'::jsonb),
    ('673332a5-3a27-4045-a929-ddbf7ff7e824'::uuid, 'period_name', '500 BC - 1 AD', '1500 - 500 BC', 'fields-wd1-2026-09-26b-s005:673332a5-3a27-4045-a929-ddbf7ff7e824:period_name', 'fields-wd1-2026-09-26b-s005 (wd1-derive-period-name): period_start -600 (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-600) = ''1500 - 500 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('673332a5-3a27-4045-a929-ddbf7ff7e824'::uuid, 'period_start', '-500', '-600', 'fields-wd1-2026-09-26b-s005:673332a5-3a27-4045-a929-ddbf7ff7e824:period_start', 'fields-wd1-2026-09-26b-s005 (wd1-replace): ''-500'' -> ''-600''', '[{"source": "https://golden-greece.gr/en/archaeological/egeo/thasos/iero-athinas-poliouxou", "url": "https://golden-greece.gr/en/archaeological/egeo/thasos/iero-athinas-poliouxou", "quote": "This monumental complex, which probably dates back to the beginning of the 5th c. BC, succeeded an older phase of the sanctuary, the first half of the 6th century BC, to which belonged a temple of which only part of the foundations and decorated cornice are preserved.", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Kouros_of_Thasos", "url": "https://en.wikipedia.org/wiki/Kouros_of_Thasos", "quote": "The Kouros of Thasos, also known as the Rambearer (Kryophoros), a statue about 3.5 meters high, was carved around 600–580 BC from local Thasian marble.", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Kouros_of_Thasos", "url": "https://en.wikipedia.org/wiki/Kouros_of_Thasos", "quote": "It was discovered in 1911 on the Acropolis of Thasos, specifically in the Pythian area, during the excavations of the French School.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0073)", "decision": "replace", "status": "MISSING", "reasoning": "Golden Greece dates the older phase of the sanctuary of Athena Poliouchos on the acropolis, with its first temple, to the first half of the 6th century BC, and Wikipedia dates the colossal Kriophoros kouros found on the acropolis in the Pythion area to around 600-580 BC; des Courtils (BCH 2020) adds that the earliest sherds from the Athena sanctuary go back to the 7th century BC. The acropolis'' history thus begins before 500 BC, in the 1500 - 500 BC bucket, not in the stored 500 BC - 1 AD one; the 6th century BC (-600) is the start the quoted sources state.", "value_page": null}]'::jsonb),
    ('674ac922-23ba-4632-a588-9f50fa1a103e'::uuid, 'period_name', '1000 - 1500 AD', '1 - 500 AD', 'fields-wd1-2026-09-26b-s005:674ac922-23ba-4632-a588-9f50fa1a103e:period_name', 'fields-wd1-2026-09-26b-s005 (wd1-derive-period-name): period_start 200 (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(200) = ''1 - 500 AD''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('674ac922-23ba-4632-a588-9f50fa1a103e'::uuid, 'period_start', '1000', '200', 'fields-wd1-2026-09-26b-s005:674ac922-23ba-4632-a588-9f50fa1a103e:period_start', 'fields-wd1-2026-09-26b-s005 (wd1-replace): ''1000'' -> ''200''', '[{"source": "https://lugares.inah.gob.mx/es/node/4350", "url": "https://lugares.inah.gob.mx/es/node/4350", "quote": "Se estima que alrededor del año 200 de nuestra era, grupos zapotecas comenzaron a establecerse en el sitio.", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Mitla", "url": "https://en.wikipedia.org/wiki/Mitla", "quote": "Mitla was inhabited at least since the Classic Period (100-650 CE)", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0096)", "decision": "replace", "status": "MISSING", "reasoning": "INAH dates the first Zapotec settlement at Mitla to around AD 200 and Wikipedia states it was inhabited at least since the Classic period (100-650 CE); an occupation from 900 BCE is only ''perhaps''. The securely attested start lies in 1-500 AD, not in the stored 1000-1500 AD bucket (1000 CE is the Mixtec takeover).", "value_page": null}]'::jsonb),
    ('6763f7a6-45af-4b74-8ef6-2cbda7cdd0e8'::uuid, 'period_name', '1 - 500 AD', NULL, 'fields-wd1-2026-09-26b-s005:6763f7a6-45af-4b74-8ef6-2cbda7cdd0e8:period_name', 'fields-wd1-2026-09-26b-s005 (wd1-derive-period-name): period_start None (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('6763f7a6-45af-4b74-8ef6-2cbda7cdd0e8'::uuid, 'period_start', '1', NULL, 'fields-wd1-2026-09-26b-s005:6763f7a6-45af-4b74-8ef6-2cbda7cdd0e8:period_start', 'fields-wd1-2026-09-26b-s005 (wd1-clear): ''1'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0106)", "decision": "clear", "status": "MISSING", "reasoning": "No source dates Ango itself; the stored 1 AD has no support. Pages on the Tantamayo complex as a whole disagree (Flornoy''s 10th-14th centuries on arqueologiadelperu.com vs Yarowilca occupation in the 12th-15th centuries on iperu.org), fall in different buckets and are not about this site, so the field is emptied.", "value_page": null}]'::jsonb),
    ('6763f7a6-45af-4b74-8ef6-2cbda7cdd0e8'::uuid, 'site_type', 'City/town/settlement', 'Citadel', 'fields-wd1-2026-09-26b-s005:6763f7a6-45af-4b74-8ef6-2cbda7cdd0e8:site_type', 'fields-wd1-2026-09-26b-s005 (wd1-replace): ''City/town/settlement'' -> ''Citadel''', '[{"source": "https://www.turismoperuano.com/sitio-arqueologico-ango-huanuco", "url": "https://www.turismoperuano.com/sitio-arqueologico-ango-huanuco", "quote": "La ciudadela fue habitada y asentada en la parte alta de una montaña a una altitud de 3900 msnm.", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Anku", "url": "https://en.wikipedia.org/wiki/Anku", "quote": "Type Citadel", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0106)", "decision": "replace", "status": "MISSING", "reasoning": "The MINCETUR tourism inventory entry (reproduced on turismoperuano.com) describes Ango as a hilltop ''ciudadela'' with portals, towers and enclosing walls, and the English Wikipedia infobox types it as a Citadel; neither calls it a town, so Citadel is the most specific fitting type.", "value_page": null}]'::jsonb),
    ('67afbdc6-2f22-4678-88aa-df76baf9f7ea'::uuid, 'site_type', 'Infrastructure', 'Monument', 'fields-wd1-2026-09-26b-s005:67afbdc6-2f22-4678-88aa-df76baf9f7ea:site_type', 'fields-wd1-2026-09-26b-s005 (wd1-replace): ''Infrastructure'' -> ''Monument''', '[{"source": "https://doa.gov.jo/EN/ListDetails/Archeological_Sites/1157/2", "url": "https://doa.gov.jo/EN/ListDetails/Archeological_Sites/1157/2", "quote": "The Nymphaeum served two main functions: The first was as a commemorative monument where citizens gathered to collect their daily water supplies.", "outcome": "found"}, {"source": "https://roamer.travel/learn/amman-roman-nymphaeum-fountain-al-balad", "url": "https://roamer.travel/learn/amman-roman-nymphaeum-fountain-al-balad", "quote": "The Roman Nymphaeum of Amman is a monumental public fountain of ancient Philadelphia, marooned and half-recovered in the middle of the modern downtown souk.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0090)", "decision": "replace", "status": "CONFLICT", "reasoning": "A nymphaeum is a monumental public fountain: the Department of Antiquities calls the Amman Nymphaeum a commemorative monument where citizens drew their water, and Roamer a monumental public fountain; Monument describes this decorated facade better than the broad Infrastructure.", "value_page": null}]'::jsonb),
    ('6814a205-8ebc-46b8-8581-94c1cbb06745'::uuid, 'geom', '0101000020E61000004B91D7FBA911364024E15D226A2B4640', 'SRID=4326;POINT(22.087591 44.339494)', 'fields-wd1-2026-09-26b-s005:6814a205-8ebc-46b8-8581-94c1cbb06745:geom', 'fields-wd1-2026-09-26b-s005 (wd1-point): 44.33917646011312, 22.068999996308133 -> 44.339494, 22.087591', '[{"source": "https://www.openstreetmap.org/node/11330637671", "url": "https://www.openstreetmap.org/node/11330637671", "quote": "Location: 44.3394940, 22.0875910", "outcome": "found"}, {"source": "https://www.wikidata.org/wiki/Q3485398", "url": "https://www.wikidata.org/wiki/Q3485398", "quote": "44°20''22.2\"N, 22°5''15.4\"E", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0126)", "decision": "replace", "status": "CONFLICT", "reasoning": "OpenStreetMap''s node for the registered archaeological site (Serbian register AN 39, linked to the register entry) and the site''s Wikidata item both give 44.3395, 22.0876, the point the national heritage register''s own map is centred on; satellite imagery shows the bare rock face of the old open pit, in which the Eneolithic shafts were found, at exactly that spot. The stored point (44.339, 22.069) is English Wikipedia''s coordinate copied from German Wikipedia''s article on the dispersed village and lies about 1.5 km to the west, in the Šaška valley.", "value_page": null}]'::jsonb),
