    ('68ff480b-a02b-4458-b131-22dff4a00df6'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Pyramid_of_Amenemhat_III_(Dahshur)', 'https://en.wikipedia.org/wiki/Black_Pyramid', 'fields-wd1-2026-09-26b-s005:68ff480b-a02b-4458-b131-22dff4a00df6:source_url', 'fields-wd1-2026-09-26b-s005 (wd1-replace): ''https://en.wikipedia.org/wiki/Pyramid_of_Amenemhat_III_(Dahshur)'' -> ''https://en.wikipedia.org/wiki/Black_Pyramid''', '[{"source": "https://en.wikipedia.org/wiki/Black_Pyramid", "url": "https://en.wikipedia.org/wiki/Black_Pyramid", "quote": "It is one of the five remaining pyramids of the original 11 pyramids at Dahshur in Egypt", "outcome": "found"}, {"source": "https://ancientegyptonline.co.uk/black-pyramid-dashur/", "url": "https://ancientegyptonline.co.uk/black-pyramid-dashur/", "quote": "The Black Pyramid of Dashur was the first pyramid built by Amenemhat III", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0025)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored URL is a redirect to the English Wikipedia article ''Black Pyramid'', which is the article about this very pyramid of Amenemhat III at Dahshur; Ancient Egypt Online independently names the same monument. The article''s own URL replaces the redirect.", "value_page": {"lang": "en", "problem": null, "resolved_title": "Black Pyramid", "unreadable": false, "wikibase_item": "Q284794"}}]'::jsonb),
