    ('6a0af920-9ec1-4fab-934f-1d96a330e386'::uuid, 'site_type', 'Temple complex', 'Monastery', 'fields-wd1-2026-09-26b-s005:6a0af920-9ec1-4fab-934f-1d96a330e386:site_type', 'fields-wd1-2026-09-26b-s005 (wd1-replace): ''Temple complex'' -> ''Monastery''', '[{"source": "https://doam.gov.pk/public/sites/6411", "url": "https://doam.gov.pk/public/sites/6411", "quote": "Type: Archaeological Site - Stupa & Monastery", "outcome": "found"}, {"source": "https://taxilamuseum.punjab.gov.pk/node/75", "url": "https://taxilamuseum.punjab.gov.pk/node/75", "quote": "the first part comprises a medley of constructions of several types and is called the stupa area; and the second part, which is located to its north, is called the monastic area.", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Dharmarajika_Stupa", "url": "https://en.wikipedia.org/wiki/Dharmarajika_Stupa", "quote": "Large-scale developments took place during the late Kushan and Kidarite era which added numerous monasteries and stupas to the site.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0103)", "decision": "replace", "status": "MISSING", "reasoning": "The national register classes Dharmarajika as a stupa and monastery, the Taxila Museum divides the complex into a stupa area and a monastic area, and Wikipedia describes its many monasteries and stupas; no source calls it a temple, so the Buddhist stupa-monastery complex is typed Monastery.", "value_page": null}]'::jsonb),
    ('6a43a3e7-66c7-4133-a91c-58a52cc5e0dc'::uuid, 'site_type', 'Megalithic structures', 'Bridge', 'fields-wd1-2026-09-26b-s005:6a43a3e7-66c7-4133-a91c-58a52cc5e0dc:site_type', 'fields-wd1-2026-09-26b-s005 (wd1-replace): ''Megalithic structures'' -> ''Bridge''', '[{"source": "https://en.wikipedia.org/wiki/El_Kantara", "url": "https://en.wikipedia.org/wiki/El_Kantara", "quote": "They also constructed an arched bridge over the river in the bottom of the gorge", "outcome": "found"}, {"source": "https://www.vitaminedz.com/fr/Algerie/le-pont-romain-d-el-kantara-7188847-Articles-0-240-1.html", "url": "https://www.vitaminedz.com/fr/Algerie/le-pont-romain-d-el-kantara-7188847-Articles-0-240-1.html", "quote": "Il est formé d’une seule arche plein cintre de 10 mètres d’ouverture et une largeur de 4,90 mètres.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0004)", "decision": "replace", "status": "CONFLICT", "reasoning": "The site is the single-arch Roman bridge over the Oued El Hai in the El Kantara gorge; Wikipedia and Vitaminedz both describe an arched bridge (Wikidata: bridge, Roman bridge). Nothing megalithic is involved.", "value_page": null}]'::jsonb),
