    ('6b926b71-b756-43c4-9bd8-f987641927da'::uuid, 'period_name', '4500 - 3000 BC', '1500 - 500 BC', 'fields-wd1-2026-09-26b-s005:6b926b71-b756-43c4-9bd8-f987641927da:period_name', 'fields-wd1-2026-09-26b-s005 (wd1-derive-period-name): period_start -700 (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-700) = ''1500 - 500 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('6b926b71-b756-43c4-9bd8-f987641927da'::uuid, 'period_start', '-4500', '-700', 'fields-wd1-2026-09-26b-s005:6b926b71-b756-43c4-9bd8-f987641927da:period_start', 'fields-wd1-2026-09-26b-s005 (wd1-replace): ''-4500'' -> ''-700''', '[{"source": "https://glosarch.org.uk/wp-content/uploads/2023/11/Cleeve-Cloud-Hillfort-and-The-Ring-for-HE-final.pdf", "url": "https://glosarch.org.uk/wp-content/uploads/2023/11/Cleeve-Cloud-Hillfort-and-The-Ring-for-HE-final.pdf", "quote": "would place the hillfort between 700-400BC.", "outcome": "found"}, {"source": "https://www.cleevecommon.org.uk/things-to-see", "url": "https://www.cleevecommon.org.uk/things-to-see", "quote": "It dates from around 500 BC and was probably built initially as a single bank and ditch, with the second ring added some two centuries later.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0032)", "decision": "replace", "status": "MISSING", "reasoning": "The 2023 GlosArch survey report for Historic England dates the hillfort to the Early Iron Age, 700-400 BC; the Cleeve Common Trust dates it to around 500 BC. The Early Iron Age start (c. 700 BC) lies in the 1500 - 500 BC bucket, not in the stored Neolithic bucket, so the value is replaced.", "value_page": null}]'::jsonb),
    ('6b926b71-b756-43c4-9bd8-f987641927da'::uuid, 'site_type', 'Fortress/citadel', 'Fort', 'fields-wd1-2026-09-26b-s005:6b926b71-b756-43c4-9bd8-f987641927da:site_type', 'fields-wd1-2026-09-26b-s005 (wd1-replace): ''Fortress/citadel'' -> ''Fort''', '[{"source": "https://www.cleevecommon.org.uk/things-to-see", "url": "https://www.cleevecommon.org.uk/things-to-see", "quote": "You can still see the shape of the Iron Age hill fort (left) above the small settlement of Nutterswood.", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Cleeve_Hill,_Gloucestershire", "url": "https://en.wikipedia.org/wiki/Cleeve_Hill,_Gloucestershire", "quote": "On its western scarp is an Iron Age hill fort", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=4693", "url": "https://www.megalithic.co.uk/article.php?sid=4693", "quote": "Type: Hillfort", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0032)", "decision": "replace", "status": "CONFLICT", "reasoning": "All sources describe the site as a small bivallate Iron Age hillfort, not a fortress or citadel; the most specific canonical type holding a hill fort is Fort.", "value_page": null}]'::jsonb),
