    ('6c736688-98d7-4c57-bf53-1f4367950131'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Le_Grand-Pressigny', 'https://de.wikipedia.org/wiki/Feuersteinmine_Le_Grand-Pressigny', 'fields-wd1-2026-09-26b-s005:6c736688-98d7-4c57-bf53-1f4367950131:source_url', 'fields-wd1-2026-09-26b-s005 (wd1-replace): ''https://en.wikipedia.org/wiki/Le_Grand-Pressigny'' -> ''https://de.wikipedia.org/wiki/Feuersteinmine_Le_Grand-Pressigny''', '[{"source": "https://de.wikipedia.org/wiki/Feuersteinmine_Le_Grand-Pressigny", "url": "https://de.wikipedia.org/wiki/Feuersteinmine_Le_Grand-Pressigny", "quote": "Die Feuersteinmine Le Grand-Pressigny in der Gemeinde Le Grand-Pressigny im Département Indre-et-Loire in Frankreich ist die Abbaustätte eines charakteristischen Feuersteins", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=6334173", "url": "https://www.megalithic.co.uk/article.php?sid=6334173", "quote": "Ancient flint mines in and around the village of Le Grand-Pressigny.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0053)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored page is about the commune. The German Wikipedia article is the only Wikipedia article about the flint mine itself, and the Megalithic Portal names the same flint mines at Le Grand-Pressigny.", "value_page": {"lang": "de", "problem": null, "resolved_title": "Feuersteinmine Le Grand-Pressigny", "unreadable": false, "wikibase_item": "Q1409728"}}]'::jsonb),
