    ('6cc9e902-c82f-4b21-9f36-41c2b783cebc'::uuid, 'period_start', '500', '1200', 'fields-wd1-2026-09-26b-s005:6cc9e902-c82f-4b21-9f36-41c2b783cebc:period_start', 'fields-wd1-2026-09-26b-s005 (wd1-replace): ''500'' -> ''1200''', '[{"source": "https://kulturarvvastmanland.se/databas/artikel/byggnader-och-arkitektur/vad-hande-med-furby", "url": "https://kulturarvvastmanland.se/databas/artikel/byggnader-och-arkitektur/vad-hande-med-furby", "quote": "Varför övergavs den medeltida gråstenskyrkan i Furby, Badelunda socken, som byggdes runt 1200-talet?", "outcome": "found"}, {"source": "https://www.werbeka.com/vasteras/bo/furbykrs.htm", "url": "https://www.werbeka.com/vasteras/bo/furbykrs.htm", "quote": "Furby eller Furuby var i början av 1200-talet, då dess gråstenskyrka ersatte en tidigare träkyrka, en egen, ganska stor socken", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0136)", "decision": "replace", "status": "MISSING", "reasoning": "The only remains at Furby are the medieval grey-stone church, which Västmanlands läns museum (Kulturarv Västmanland) and werbeka.com both date to the 1200s (13th century); nothing dates a 6th-century mound here, so the stored 500 is replaced by 1200, the first year of the 1200s (bucket 1000-1500 AD).", "value_page": null}]'::jsonb),
