    ('6cef20ff-4a03-4476-a80e-b44447f6764a'::uuid, 'site_type', 'Temple complex', 'Church', 'fields-wd1-2026-09-26b-s005:6cef20ff-4a03-4476-a80e-b44447f6764a:site_type', 'fields-wd1-2026-09-26b-s005 (wd1-replace): ''Temple complex'' -> ''Church''', '[{"source": "https://www.sussex.ac.uk/byzantine/mosaic/view/structure/id/377", "url": "https://www.sussex.ac.uk/byzantine/mosaic/view/structure/id/377", "quote": "Type of structure: Church", "outcome": "found"}, {"source": "https://www.culture.gov.cy/dmculture/da/da.nsf/d49133d713b3ff4fc22576c70031d30e/285f9de804fdf2c2422577ae0045e674", "url": "https://www.culture.gov.cy/dmculture/da/da.nsf/d49133d713b3ff4fc22576c70031d30e/285f9de804fdf2c2422577ae0045e674", "quote": "The first church was investigated between the years 2007-2010 and belongs to three-aisled transept basilica type, a variation of the cruciform type.", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Katalymata_ton_Plakoton", "url": "https://en.wikipedia.org/wiki/Katalymata_ton_Plakoton", "quote": "In December 2018, a Byzantine church with mosaics including inscriptions in perfect condition dating back to the reign of Emperor Heraclius was discovered", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0019)", "decision": "replace", "status": "CONFLICT", "reasoning": "The Cyprus Department of Antiquities describes a complex of two monumental churches (basilicas) around an atrium, the Sussex database types the structure as a Church and Wikipedia calls it a Byzantine church; it is a Christian church complex, not a temple complex, so the most specific canonical type is Church.", "value_page": null}]'::jsonb),
