    ('6cf9cf72-ba27-4843-bbd4-e9acfabec124'::uuid, 'period_start', '1000', NULL, 'fields-wd1-2026-09-26b-s005:6cf9cf72-ba27-4843-bbd4-e9acfabec124:period_start', 'fields-wd1-2026-09-26b-s005 (wd1-clear): ''1000'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0115)", "decision": "clear", "status": "MISSING", "reasoning": "No source dates the start of the site. The SAA abstract only dates the Inca Empire (ca. 1400-1533 CE), and Kosiba''s project reports that the shrine was established before the Inca rise, without a date. Nothing supports the stored 1000, so the field is emptied.", "value_page": null}]'::jsonb),
    ('6cf9cf72-ba27-4843-bbd4-e9acfabec124'::uuid, 'site_type', 'Monument', 'Sacred site', 'fields-wd1-2026-09-26b-s005:6cf9cf72-ba27-4843-bbd4-e9acfabec124:site_type', 'fields-wd1-2026-09-26b-s005 (wd1-replace): ''Monument'' -> ''Sacred site''', '[{"source": "https://andina.pe/agencia/noticia-buscan-declarar-santuario-historico-a-legendario-cerro-huanacaure-cusco-219009.aspx", "url": "https://andina.pe/agencia/noticia-buscan-declarar-santuario-historico-a-legendario-cerro-huanacaure-cusco-219009.aspx", "quote": "Según las crónicas españolas y la mitología andina, el Huanacaure constituye la huaca y oráculo más importante de la cultura incaica. Este promontorio rocoso posee en su parte alta edificaciones arqueológicas religiosas", "outcome": "found"}, {"source": "https://www.pachaexpeditions.com/blog/tracing-the-origins-of-huanacauri-hill-and-its-impact-on-cuscos-development/", "url": "https://www.pachaexpeditions.com/blog/tracing-the-origins-of-huanacauri-hill-and-its-impact-on-cuscos-development/", "quote": "The incorporation of Huanacauri into this sacred network marked it as a place of pilgrimage and ritual.", "outcome": "found"}, {"source": "WD1 decision (counted, round 1, wd1-r1-b0020)", "decision": "replace", "status": "CONFLICT", "reasoning": "Huanacauri (Wanakawri) is not a monument in the sense of a built memorial: the Peruvian news agency Andina, citing the chronicles, calls it the most important huaca and oracle of Inca culture with religious archaeological buildings on its upper part, and a Cusco tour operator''s history page describes it as part of the Incas'' sacred network, a place of pilgrimage and ritual. Both describe a sacred site, so the stored Monument is replaced.", "value_page": null}]'::jsonb),
