    ('6d4a0330-a271-4d2d-a0c8-2a5f768e78af'::uuid, 'site_type', 'Megalithic stones', 'City', 'fields-wd1-2026-09-26b-s005:6d4a0330-a271-4d2d-a0c8-2a5f768e78af:site_type', 'fields-wd1-2026-09-26b-s005 (wd1-replace): ''Megalithic stones'' -> ''City''', '[{"source": "https://en.wikipedia.org/wiki/Oricum", "url": "https://en.wikipedia.org/wiki/Oricum", "quote": "Oricum later became an important Roman city between the provinces of Epirus Vetus and Epirus Nova in Macedonia. It is now an archaeological park of Albania, near modern Orikum, Vlorë County.", "outcome": "found"}, {"source": "http://octopusfoundation.org/en/project/ancient-port-oricum-albania-2017-underwater-archaeology-history-caesar/", "url": "http://octopusfoundation.org/en/project/ancient-port-oricum-albania-2017-underwater-archaeology-history-caesar/", "quote": "Of the many archaeological treasures in Albania, the ancient port of Oricum is arguably one of the most intriguing. This forgotten city played a crucial role in Julius Caesar’s ascent to total domination.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0002)", "decision": "replace", "status": "CONFLICT", "reasoning": "The archaeological park preserves the ancient Greek polis and Roman city of Oricum (Wikipedia, Octopus Foundation); it is a city site, not megalithic stones.", "value_page": null}]'::jsonb),
