    ('6d84eb20-870b-43b1-ba78-25e3a0e4954f'::uuid, 'site_type', 'Rock relief/carving', 'Sculptured stone', 'fields-wd1-2026-09-26b-s005:6d84eb20-870b-43b1-ba78-25e3a0e4954f:site_type', 'fields-wd1-2026-09-26b-s005 (wd1-replace): ''Rock relief/carving'' -> ''Sculptured stone''', '[{"source": "https://en.wikipedia.org/wiki/Stone_spheres_of_Costa_Rica", "url": "https://en.wikipedia.org/wiki/Stone_spheres_of_Costa_Rica", "quote": "They are the best-known stone sculptures of the Isthmo-Colombian area.", "outcome": "found"}, {"source": "https://www.specialplacesofcostarica.com/blog/finca-6/", "url": "https://www.specialplacesofcostarica.com/blog/finca-6/", "quote": "The spheres, some more than two meters in diameter, were carved from local rocks like gabbro, granite, and sandstone.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0016)", "decision": "replace", "status": "MISSING", "reasoning": "Wikipedia calls the spheres the best-known stone sculptures of the Isthmo-Colombian area, and Special Places of Costa Rica describes them as carved from gabbro, granite and sandstone. They are free-standing sculptured stones, not a relief or rock carving.", "value_page": null}]'::jsonb),
