    ('6e1f996c-be31-4337-bd80-7a94b03a3d05'::uuid, 'period_start', '-20000', NULL, 'fields-wd1-2026-09-26b-s005:6e1f996c-be31-4337-bd80-7a94b03a3d05:period_start', 'fields-wd1-2026-09-26b-s005 (wd1-clear): ''-20000'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0099)", "decision": "clear", "status": "MISSING", "reasoning": "Every source I found dates the paintings only as Upper Palaeolithic, ''20,000-15,000 years ago'' (Mongolian Cave Research Association, Mongoltoli) or ''40,000 years ago'' (Mongolian Wikipedia). No source gives a BC year, century or millennium, so no readable start year can be sourced.", "value_page": null}]'::jsonb),
    ('6e2e27d0-f162-4a26-bd66-b7fc75554ce4'::uuid, 'geom', '0101000020E6100000DB847F9BAE0752C005370DF0D09E2AC0', 'SRID=4326;POINT(-72.43 -13.22611)', 'fields-wd1-2026-09-26b-s005:6e2e27d0-f162-4a26-bd66-b7fc75554ce4:geom', 'fields-wd1-2026-09-26b-s005 (wd1-point): -13.310187818158292, -72.12003219082855 -> -13.22611, -72.43', '[{"source": "https://www.geonames.org/6393222", "url": "https://www.geonames.org/6393222", "quote": "Coordinates -13.22611, -72.43000", "outcome": "found"}, {"source": "https://de.wikipedia.org/wiki/R%C3%ADo_Cusichaca", "url": "https://de.wikipedia.org/wiki/R%C3%ADo_Cusichaca", "quote": "13° 13′ 36″ S, 72° 25′ 49″ W", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0107)", "decision": "replace", "status": "CONFLICT", "reasoning": "GeoNames (Río Cusichaca) and the German Wikipedia article give the river''s confluence with the Urubamba at Km 88, where Patallacta and the Cusichaca Project''s sites lie, within 50 m of each other; the stored point is the town of Urubamba, about 34 km east, so it is replaced by the confluence point.", "value_page": null}]'::jsonb),
