    ('6e2e27d0-f162-4a26-bd66-b7fc75554ce4'::uuid, 'lon', '-72.12003219082855', '-72.43', 'fields-wd1-2026-09-26b-s005:6e2e27d0-f162-4a26-bd66-b7fc75554ce4:lon', 'fields-wd1-2026-09-26b-s005 (wd1-replace): -13.310187818158292, -72.12003219082855 -> -13.22611, -72.43', '[{"source": "https://www.geonames.org/6393222", "url": "https://www.geonames.org/6393222", "quote": "Coordinates -13.22611, -72.43000", "outcome": "found"}, {"source": "https://de.wikipedia.org/wiki/R%C3%ADo_Cusichaca", "url": "https://de.wikipedia.org/wiki/R%C3%ADo_Cusichaca", "quote": "13° 13′ 36″ S, 72° 25′ 49″ W", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0107)", "decision": "replace", "status": "CONFLICT", "reasoning": "GeoNames (Río Cusichaca) and the German Wikipedia article give the river''s confluence with the Urubamba at Km 88, where Patallacta and the Cusichaca Project''s sites lie, within 50 m of each other; the stored point is the town of Urubamba, about 34 km east, so it is replaced by the confluence point.", "value_page": null}]'::jsonb),
    ('6e2e27d0-f162-4a26-bd66-b7fc75554ce4'::uuid, 'period_name', '1000 - 1500 AD', '1500 - 500 BC', 'fields-wd1-2026-09-26b-s005:6e2e27d0-f162-4a26-bd66-b7fc75554ce4:period_name', 'fields-wd1-2026-09-26b-s005 (wd1-derive-period-name): period_start -700 (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-700) = ''1500 - 500 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('6e2e27d0-f162-4a26-bd66-b7fc75554ce4'::uuid, 'period_start', '1000', '-700', 'fields-wd1-2026-09-26b-s005:6e2e27d0-f162-4a26-bd66-b7fc75554ce4:period_start', 'fields-wd1-2026-09-26b-s005 (wd1-replace): ''1000'' -> ''-700''', '[{"source": "https://atom.aim25.com/index.php/the-cusichaca-trust-2", "url": "https://atom.aim25.com/index.php/the-cusichaca-trust-2", "quote": "Archaeological excavation at the Inca site of Huillca Raccay and at other sites around and above the junction of the Cusichaca and Urubamba rivers, revealed a sequence of distinct occupations from c.700 BC to the time of the Spanish conquest in the 1530s.", "outcome": "found"}, {"source": "https://docslib.org/doc/10971231/continuity-and-change-in-the-formative-period-of-the-cusichaca-valley-department-of-cuzco-peru", "url": "https://docslib.org/doc/10971231/continuity-and-change-in-the-formative-period-of-the-cusichaca-valley-department-of-cuzco-peru", "quote": "Excavation of well-stratified occupation deposits on the Huillca Raccay promontory in the Cusichaca Valley has revealed a sequence of activity dating from c 600 BC to AD 100.", "outcome": "found"}, {"source": "WD1 decision (counted, round 1, wd1-r1-b0019)", "decision": "replace", "status": "MISSING", "reasoning": "The Cusichaca Trust archive catalogue (AIM25) dates the excavated sequence of occupations in the Cusichaca valley from c.700 BC, and the UCL doctoral thesis on the valley''s Formative period independently dates the stratified occupation at Huillca Raccay from c 600 BC; both put the first occupation in the 1500-500 BC bucket, not the Inca-era 1000-1500 AD bucket, so the earliest attested start is c. 700 BC.", "value_page": null}]'::jsonb),
