    ('6f2ea7d4-4858-46e6-a24f-0c9d49109741'::uuid, 'site_type', 'Fortress/citadel', 'Fort', 'fields-wd1-2026-09-26b-s005:6f2ea7d4-4858-46e6-a24f-0c9d49109741:site_type', 'fields-wd1-2026-09-26b-s005 (wd1-replace): ''Fortress/citadel'' -> ''Fort''', '[{"source": "https://en.wikipedia.org/wiki/Burnham_Beeches", "url": "https://en.wikipedia.org/wiki/Burnham_Beeches", "quote": "Seven Ways Plain hill fort is located in the south west part of Burnham Beeches.", "outcome": "found"}, {"source": "https://heritageportal.buckinghamshire.gov.uk/Monument/MBC4607", "url": "https://heritageportal.buckinghamshire.gov.uk/Monument/MBC4607", "quote": "Iron Age hillfort called Seven Ways Plain in Burnham Beeches", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0029)", "decision": "replace", "status": "CONFLICT", "reasoning": "Wikipedia and the Buckinghamshire HER describe the site as the Seven Ways Plain hill fort, a slight univallate hillfort; the canonical type for a hillfort is Fort rather than Fortress/citadel.", "value_page": null}]'::jsonb),
    ('6f2ea7d4-4858-46e6-a24f-0c9d49109741'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Burnham_Beeches', 'https://heritageportal.buckinghamshire.gov.uk/Monument/MBC4607', 'fields-wd1-2026-09-26b-s005:6f2ea7d4-4858-46e6-a24f-0c9d49109741:source_url', 'fields-wd1-2026-09-26b-s005 (wd1-replace): ''https://en.wikipedia.org/wiki/Burnham_Beeches'' -> ''https://heritageportal.buckinghamshire.gov.uk/Monument/MBC4607''', '[{"source": "https://heritageportal.buckinghamshire.gov.uk/Monument/MBC4607", "url": "https://heritageportal.buckinghamshire.gov.uk/Monument/MBC4607", "quote": "Iron Age hillfort called Seven Ways Plain in Burnham Beeches", "outcome": "found"}, {"source": "https://www.chilterns.org.uk/our-landscape/history-heritage/prehistoric-chilterns/hillforts/sevenwaysplain/", "url": "https://www.chilterns.org.uk/our-landscape/history-heritage/prehistoric-chilterns/hillforts/sevenwaysplain/", "quote": "Seven Ways Plain, the remains of an Iron Age hillfort at the southern end of Lord Mayors drive.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0029)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored article is about the Burnham Beeches nature reserve; the hillfort has no Wikipedia article, so the Buckinghamshire Historic Environment Record entry for the Seven Ways Plain hillfort, a heritage register page about this very site, replaces it.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
    ('6f502f33-3251-4054-b334-4fa52ea7b671'::uuid, 'site_type', 'Megalithic stones', 'Barrow', 'fields-wd1-2026-09-26b-s005:6f502f33-3251-4054-b334-4fa52ea7b671:site_type', 'fields-wd1-2026-09-26b-s005 (wd1-replace): ''Megalithic stones'' -> ''Barrow''', '[{"source": "https://en.wikipedia.org/wiki/Coldrum_Long_Barrow", "url": "https://en.wikipedia.org/wiki/Coldrum_Long_Barrow", "quote": "is a chambered long barrow located near the village of Trottiscliffe in the south-eastern English county of Kent", "outcome": "found"}, {"source": "https://heritage.kent.gov.uk/Monument/mke1449", "url": "https://heritage.kent.gov.uk/Monument/mke1449", "quote": "CHAMBERED LONG BARROW (Early Neolithic - 3980 BC to 3540 BC)", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0032)", "decision": "replace", "status": "CONFLICT", "reasoning": "Wikipedia and the Kent Historic Environment Record both classify the site as a chambered long barrow, a Neolithic burial mound with a sarsen chamber; Barrow is more specific than the generic ''Megalithic stones''.", "value_page": null}]'::jsonb),
    ('6f91fd7b-d4db-43d8-ab5c-3aef866d4430'::uuid, 'period_name', '500 BC - 1 AD', NULL, 'fields-wd1-2026-09-26b-s005:6f91fd7b-d4db-43d8-ab5c-3aef866d4430:period_name', 'fields-wd1-2026-09-26b-s005 (wd1-derive-period-name): period_start None (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('6f91fd7b-d4db-43d8-ab5c-3aef866d4430'::uuid, 'period_start', '-500', NULL, 'fields-wd1-2026-09-26b-s005:6f91fd7b-d4db-43d8-ab5c-3aef866d4430:period_start', 'fields-wd1-2026-09-26b-s005 (wd1-clear): ''-500'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0146)", "decision": "clear", "status": "MISSING", "reasoning": "Wikipedia only says the settlement dates back to the Hellenistic (Seleucid) era without a year or century; no second reputable source with a stated year or century for the foundation could be found (the one page with a century, mirasharitasi, claims an unfounded Lydian 8th-century BC origin).", "value_page": null}]'::jsonb),
    ('6faee7c5-517c-4de4-9809-b98a481fff2a'::uuid, 'site_type', 'Megalithic stones', 'Settlement', 'fields-wd1-2026-09-26b-s005:6faee7c5-517c-4de4-9809-b98a481fff2a:site_type', 'fields-wd1-2026-09-26b-s005 (wd1-replace): ''Megalithic stones'' -> ''Settlement''', '[{"source": "https://www.sanliurfa.bel.tr/lang/en/icerik/209/7/-ancient-city-of-shuayb-", "url": "https://www.sanliurfa.bel.tr/lang/en/icerik/209/7/-ancient-city-of-shuayb-", "quote": "The Ancient City of Şuayb is a settlement dating back to the Late Roman period (4th-5th centuries AD).", "outcome": "found"}, {"source": "https://www.urfakulturatlasi.com.tr/envanter/detay/suayip-antik-kenti", "url": "https://www.urfakulturatlasi.com.tr/envanter/detay/suayip-antik-kenti", "quote": "Kent, özellikle Soğmatar Kutsal Alanı ile birlikte Tek Tek Dağları Milli Parkı içinde önemli bir kırsal yerleşim alanıdır.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0148)", "decision": "replace", "status": "MISSING", "reasoning": "The municipality calls it a settlement of the Late Roman period with Roman-style houses, and the Şanlıurfa Cultural Atlas (provincial governorate inventory) calls it an important rural settlement area (kırsal yerleşim alanı). No source mentions megalithic stones; it is a Late Roman settlement with rock-cut tombs and cisterns.", "value_page": null}]'::jsonb),
    ('6faee7c5-517c-4de4-9809-b98a481fff2a'::uuid, 'source_url', 'https://www-sanliurfa-bel-tr.translate.goog/icerik/236/625/suayb-antik-sehri?_x_tr_sl=tr&_x_tr_tl=en&_x_tr_hl=en&_x_tr_pto=sc', 'https://www.urfakulturatlasi.com.tr/envanter/detay/suayip-antik-kenti', 'fields-wd1-2026-09-26b-s005:6faee7c5-517c-4de4-9809-b98a481fff2a:source_url', 'fields-wd1-2026-09-26b-s005 (wd1-replace): ''https://www-sanliurfa-bel-tr.translate.goog/icerik/236/625/suayb-antik-sehri?_x_tr_sl=tr&_x_tr_tl=en&_x_tr_hl=en&_x_tr_pto=sc'' -> ''https://www.urfakulturatlasi.com.tr/envanter/detay/suayip-antik-kenti''', '[{"source": "https://www.urfakulturatlasi.com.tr/envanter/detay/suayip-antik-kenti", "url": "https://www.urfakulturatlasi.com.tr/envanter/detay/suayip-antik-kenti", "quote": "Şuayip (Şuayb) Antik Kenti, Şanlıurfa ili, Harran ilçesi, Şuayip Şehri (Özkent) Mahallesi’nde yer almaktadır.", "outcome": "found"}, {"source": "https://www.kulturportali.gov.tr/turkiye/sanliurfa/gezilecekyer/suayb-antik-kenti--suayip-sehri-", "url": "https://www.kulturportali.gov.tr/turkiye/sanliurfa/gezilecekyer/suayb-antik-kenti--suayip-sehri-", "quote": "Şuayb Antik Kenti, Geç Roma döneminde (MS 4-5. yüzyıl) kurulduğu düşünülen bir yerleşim yeridir.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0148)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored URL is a Google Translate proxy of the municipality page, not a page about the site. The Şanlıurfa Cultural Atlas entry Şuayip Antik Kenti (Harran, Şuayip Şehri neighbourhood) is the provincial inventory entry for this very site, and the Ministry''s culture portal has its own entry for it.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
    ('70037a24-6487-4834-9b50-5242289009fe'::uuid, 'site_type', 'Residence/villa/farmhouse', 'Bath', 'fields-wd1-2026-09-26b-s005:70037a24-6487-4834-9b50-5242289009fe:site_type', 'fields-wd1-2026-09-26b-s005 (wd1-replace): ''Residence/villa/farmhouse'' -> ''Bath''', '[{"source": "https://en.wikipedia.org/wiki/Roman_Bath,_York", "url": "https://en.wikipedia.org/wiki/Roman_Bath,_York", "quote": "The Roman Bath is a Grade II* listed public house on St Sampson''s Square in the city of York, England. It is built above an ancient Roman bath house.", "outcome": "found"}, {"source": "https://her.york.gov.uk/Monument/MYO917", "url": "https://her.york.gov.uk/Monument/MYO917", "quote": "Public house, built in 1929-31, to designs by B Wilson, incorporating parts of a Roman bath in the cellar. The baths date to the 4th century and comprise three rooms and hypocaust.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0044)", "decision": "replace", "status": "CONFLICT", "reasoning": "Both sources describe the ancient site as a Roman bath house (caldarium, frigidarium and hypocaust) beneath the pub, not a residence or villa, so the type is Bath.", "value_page": null}]'::jsonb),
    ('70695bd4-a360-48f4-a684-a971cc281636'::uuid, 'site_type', 'Ruin', 'Settlement', 'fields-wd1-2026-09-26b-s005:70695bd4-a360-48f4-a684-a971cc281636:site_type', 'fields-wd1-2026-09-26b-s005 (wd1-replace): ''Ruin'' -> ''Settlement''', '[{"source": "https://en.wikipedia.org/wiki/Akkale", "url": "https://en.wikipedia.org/wiki/Akkale", "quote": "the complex was not a castle, but a small, wealthy settlement.", "outcome": "found"}, {"source": "https://akkale.mersin.edu.tr/page1.html", "url": "https://akkale.mersin.edu.tr/page1.html", "quote": "Yerleşimde tespit edilen çok sayıda kalıntı da burasının bir liman yerleşimi olarak kurulduğunu ve bu çerçevede geliştiğinin kanıtlarına sahiptir.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0140)", "decision": "replace", "status": "CONFLICT", "reasoning": "Wikipedia calls Akkale a small, wealthy settlement rather than a castle, and the Mersin University excavation team describes it as an ancient port settlement (liman yerleşimi) with an inn, baths, two cisterns, a church and a tomb; the great cistern is only one part of it, so Settlement is more specific than the generic Ruin.", "value_page": null}]'::jsonb),
    ('706c0a4d-f0ba-4970-8744-176841caae61'::uuid, 'period_name', '500 - 1000 AD', NULL, 'fields-wd1-2026-09-26b-s005:706c0a4d-f0ba-4970-8744-176841caae61:period_name', 'fields-wd1-2026-09-26b-s005 (wd1-derive-period-name): period_start None (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
