    ('70762563-db82-43f3-ad30-bce5fde9c9bd'::uuid, 'period_name', '4500 - 3000 BC', '500 - 1000 AD', 'fields-wd1-2026-09-26b-s005:70762563-db82-43f3-ad30-bce5fde9c9bd:period_name', 'fields-wd1-2026-09-26b-s005 (wd1-derive-period-name): period_start 700 (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(700) = ''500 - 1000 AD''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('70762563-db82-43f3-ad30-bce5fde9c9bd'::uuid, 'period_start', '-4500', '700', 'fields-wd1-2026-09-26b-s005:70762563-db82-43f3-ad30-bce5fde9c9bd:period_start', 'fields-wd1-2026-09-26b-s005 (wd1-replace): ''-4500'' -> ''700''', '[{"source": "https://en.wikipedia.org/wiki/Sigiburg", "url": "https://en.wikipedia.org/wiki/Sigiburg", "quote": "The hillfort was raised ca. 700 by Westphalian Saxons.", "outcome": "found"}, {"source": "https://www.lwl.org/fremde-impulse-download/start/LWL/Kultur/fremde-impulse/die_baudenkmale/Impuls-Syburg-Westhofen/Saechsische-Wallanlage-Hohensyburg.html", "url": "https://www.lwl.org/fremde-impulse-download/start/LWL/Kultur/fremde-impulse/die_baudenkmale/Impuls-Syburg-Westhofen/Saechsische-Wallanlage-Hohensyburg.html", "quote": "In diesem Zusammenhang erbauten die Sachsen die Sigiburg auf dem Syberg etwa um das Jahr 700 n. Chr.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0059)", "decision": "replace", "status": "MISSING", "reasoning": "English Wikipedia and the LWL (Westphalian regional heritage body) both date the building of the Saxon Sigiburg on the Syberg to c. AD 700, matching the LWL Altertumskommission''s 8th-9th-century finds; the stored c. 4500 BC rests only on undated Neolithic stray finds and lies in the wrong bucket.", "value_page": null}]'::jsonb),
    ('70762563-db82-43f3-ad30-bce5fde9c9bd'::uuid, 'site_type', 'City/town/settlement', 'Castle', 'fields-wd1-2026-09-26b-s005:70762563-db82-43f3-ad30-bce5fde9c9bd:site_type', 'fields-wd1-2026-09-26b-s005 (wd1-replace): ''City/town/settlement'' -> ''Castle''', '[{"source": "https://en.wikipedia.org/wiki/Sigiburg", "url": "https://en.wikipedia.org/wiki/Sigiburg", "quote": "The ruins of the later Hohensyburg castle now stand on the site", "outcome": "found"}, {"source": "https://www.alleburgen.de/bd.php?id=19134", "url": "https://www.alleburgen.de/bd.php?id=19134", "quote": "Wallburg mit Ruinen einer mittelalterlichen Burg in der SO-Ecke", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0059)", "decision": "replace", "status": "CONFLICT", "reasoning": "The sources describe the site as a Saxon ramparted castle (Wallburg, Sigiburg) with the ruins of the medieval Hohensyburg castle in its corner, not a town or settlement; Castle is the canonical type that holds both phases.", "value_page": null}]'::jsonb),
    ('70762563-db82-43f3-ad30-bce5fde9c9bd'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Syberg', 'https://en.wikipedia.org/wiki/Sigiburg', 'fields-wd1-2026-09-26b-s005:70762563-db82-43f3-ad30-bce5fde9c9bd:source_url', 'fields-wd1-2026-09-26b-s005 (wd1-replace): ''https://en.wikipedia.org/wiki/Syberg'' -> ''https://en.wikipedia.org/wiki/Sigiburg''', '[{"source": "https://en.wikipedia.org/wiki/Sigiburg", "url": "https://en.wikipedia.org/wiki/Sigiburg", "quote": "The Sigiburg was a Saxon hillfort in Western Germany, overlooking the River Ruhr near its confluence with the River Lenne.", "outcome": "found"}, {"source": "https://www.lwl.org/fremde-impulse-download/start/LWL/Kultur/fremde-impulse/die_baudenkmale/Impuls-Syburg-Westhofen/Saechsische-Wallanlage-Hohensyburg.html", "url": "https://www.lwl.org/fremde-impulse-download/start/LWL/Kultur/fremde-impulse/die_baudenkmale/Impuls-Syburg-Westhofen/Saechsische-Wallanlage-Hohensyburg.html", "quote": "In diesem Zusammenhang erbauten die Sachsen die Sigiburg auf dem Syberg etwa um das Jahr 700 n. Chr.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0059)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored article is about the hill; the archaeological site on it, the Sigiburg/Hohensyburg, has its own English Wikipedia article, and the LWL page confirms the Sigiburg on the Syberg.", "value_page": {"lang": "en", "problem": null, "resolved_title": "Sigiburg", "unreadable": false, "wikibase_item": "Q25247879"}}]'::jsonb),
    ('708e01e6-3b2f-4c7f-924b-42e319169c68'::uuid, 'site_type', 'Megalithic stones', 'Archaeological site', 'fields-wd1-2026-09-26b-s005:708e01e6-3b2f-4c7f-924b-42e319169c68:site_type', 'fields-wd1-2026-09-26b-s005 (wd1-replace): ''Megalithic stones'' -> ''Archaeological site''', '[{"source": "https://madainproject.com/pnyx", "url": "https://madainproject.com/pnyx", "quote": "The Pnyx (Pnyka), is an notable archaeological site in Athens where the Athenian Assembly (Ekklesia) met to debate and make decisions on matters of state.", "outcome": "found"}, {"source": "https://www.traveldojo.com/pnyx/", "url": "https://www.traveldojo.com/pnyx/", "quote": "The Pnyx is an archaeological site visited for its clear association with classical Athenian political life rather than for monumental architecture.", "outcome": "found"}, {"source": "http://odysseus.culture.gr/h/3/eh352.jsp?obj_id=2580", "url": "http://odysseus.culture.gr/h/3/eh352.jsp?obj_id=2580", "quote": "it was securely identified as the Pnyx, the place where the Assembly of the Athenians held its meetings", "outcome": "found"}, {"source": "WD1 decision (counted, round 1, wd1-r1-b0009)", "decision": "replace", "status": "CONFLICT", "reasoning": "The Pnyx west of the Acropolis in Athens is described as an archaeological site and as the meeting place of the Athenian Assembly (bema, terraced auditorium, stoas), with nothing megalithic about it; no canonical type names an assembly place, so the generic ''Archaeological site'' is the one that holds what the sources say.", "value_page": null}]'::jsonb),
    ('70947922-0b34-4e73-b6b0-8a13f2ff3806'::uuid, 'period_name', '500 BC - 1 AD', '1 - 500 AD', 'fields-wd1-2026-09-26b-s005:70947922-0b34-4e73-b6b0-8a13f2ff3806:period_name', 'fields-wd1-2026-09-26b-s005 (wd1-derive-period-name): period_start 201 (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(201) = ''1 - 500 AD''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('70947922-0b34-4e73-b6b0-8a13f2ff3806'::uuid, 'period_start', '-18', '201', 'fields-wd1-2026-09-26b-s005:70947922-0b34-4e73-b6b0-8a13f2ff3806:period_start', 'fields-wd1-2026-09-26b-s005 (wd1-replace): ''-18'' -> ''201''', '[{"source": "https://english.seoul.go.kr/awakening-baekje-500-years-pungnaptoseong-fortress/", "url": "https://english.seoul.go.kr/awakening-baekje-500-years-pungnaptoseong-fortress/", "quote": "resulting in the unearthing of many artifacts and relics from the third century, when the city of Hanseong was the capital of Baekje.", "outcome": "found"}, {"source": "https://www.korea.net/NewsFocus/Culture/view?articleId=123461", "url": "https://www.korea.net/NewsFocus/Culture/view?articleId=123461", "quote": "According to the results, construction of the eastern wall started in the mid-to-late 200s and was completed in the early-middle of the 300s.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0127)", "decision": "replace", "status": "MISSING", "reasoning": "The stored -18 is the traditional founding year of the Baekje kingdom (18 BC), not a date for this site. The Seoul Metropolitan Government reports that the 1997 emergency excavation at Pungnaptoseong yielded relics from the third century, the earliest Hanseong period. Korea.net reports NRICH''s radiocarbon and OSL results dating the start of the wall''s construction to the mid-to-late 200s. Both place the site''s start in the 3rd century AD, in the 1 - 500 AD bucket.", "value_page": null}]'::jsonb),
    ('70947922-0b34-4e73-b6b0-8a13f2ff3806'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Pungnaptoseong', 'https://en.wikipedia.org/wiki/P%27ungnapt%27os%C5%8Fng', 'fields-wd1-2026-09-26b-s005:70947922-0b34-4e73-b6b0-8a13f2ff3806:source_url', 'fields-wd1-2026-09-26b-s005 (wd1-replace): ''https://en.wikipedia.org/wiki/Pungnaptoseong'' -> ''https://en.wikipedia.org/wiki/P%27ungnapt%27os%C5%8Fng''', '[{"source": "https://en.wikipedia.org/wiki/P%27ungnapt%27os%C5%8Fng", "url": "https://en.wikipedia.org/wiki/P%27ungnapt%27os%C5%8Fng", "quote": "it has been speculated that Pungnap Toseong was Hanam Wiryeseong", "outcome": "found"}, {"source": "https://www.songpa.go.kr/eng/contents.do?key=3926", "url": "https://www.songpa.go.kr/eng/contents.do?key=3926", "quote": "This is an earthen wall, generally called Pungnap Toseong, built on a flat area around the Hangang River.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0127)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored URL ''Pungnaptoseong'' is only a redirect. The article it resolves to, English Wikipedia ''P''ungnapt''osŏng'', is about this earthen fortification in Pungnap-dong. Songpa-gu''s own page describes the same Pungnap Toseong wall.", "value_page": {"lang": "en", "problem": null, "resolved_title": "P''ungnapt''osŏng", "unreadable": false, "wikibase_item": "Q11282530"}}]'::jsonb),
    ('70ba6d0f-f026-4b29-9379-a9152ee1e271'::uuid, 'site_type', 'Fortress/citadel', 'Fort', 'fields-wd1-2026-09-26b-s005:70ba6d0f-f026-4b29-9379-a9152ee1e271:site_type', 'fields-wd1-2026-09-26b-s005 (wd1-replace): ''Fortress/citadel'' -> ''Fort''', '[{"source": "https://en.wikipedia.org/wiki/Fin_Cop", "url": "https://en.wikipedia.org/wiki/Fin_Cop", "quote": "Fin Cop is a hill and an associated Iron Age hill fort in Monsal Dale, close to Ashford in the Water in Derbyshire, England.", "outcome": "found"}, {"source": "https://her.derbyshire.gov.uk/Monument/MDR2043", "url": "https://her.derbyshire.gov.uk/Monument/MDR2043", "quote": "It includes a Late Bronze Age or Early Iron Age promontory fort and, within the area covered by the fort, an Early Bronze Age bowl barrow", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0034)", "decision": "replace", "status": "CONFLICT", "reasoning": "Wikipedia and the Derbyshire Historic Environment Record describe Fin Cop as a hill fort / promontory fort, a defended enclosure; Fort names that type more exactly than Fortress/citadel.", "value_page": null}]'::jsonb),
    ('70c04f92-593e-467b-8568-b585e1cdb58f'::uuid, 'period_name', '3000 - 1500 BC', NULL, 'fields-wd1-2026-09-26b-s005:70c04f92-593e-467b-8568-b585e1cdb58f:period_name', 'fields-wd1-2026-09-26b-s005 (wd1-derive-period-name): period_start None (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('70c04f92-593e-467b-8568-b585e1cdb58f'::uuid, 'period_start', '-2500', NULL, 'fields-wd1-2026-09-26b-s005:70c04f92-593e-467b-8568-b585e1cdb58f:period_start', 'fields-wd1-2026-09-26b-s005 (wd1-clear): ''-2500'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0039)", "decision": "clear", "status": "MISSING", "reasoning": "Little Meg is unexcavated by modern methods and undated: Wikipedia calls it ''more likely to be a Bronze Age (c.2,500 - c.700 B.C.) kerb cairn'', which is the span of the whole period, and stone-circles.org.uk and the Megalithic Portal say only ''perhaps from the Bronze Age'' / Neolithic and Bronze Age; no second independent source gives a year or century for its construction.", "value_page": null}]'::jsonb),
    ('70c04f92-593e-467b-8568-b585e1cdb58f'::uuid, 'site_type', 'Stone circle', 'Cairn', 'fields-wd1-2026-09-26b-s005:70c04f92-593e-467b-8568-b585e1cdb58f:site_type', 'fields-wd1-2026-09-26b-s005 (wd1-replace): ''Stone circle'' -> ''Cairn''', '[{"source": "https://en.wikipedia.org/wiki/Little_Meg", "url": "https://en.wikipedia.org/wiki/Little_Meg", "quote": "Little Meg (also known as the Maughanby circle) is a small circle of large kerb stones which probably surrounded a Bronze Age kerb cairn.", "outcome": "found"}, {"source": "http://www.stone-circles.org.uk/stone/littlemeg.htm", "url": "http://www.stone-circles.org.uk/stone/littlemeg.htm", "quote": "Although the stones of Little Meg are sometimes referred to as a small stone circle, they are in fact the remains of a burial mound or round cairn.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0039)", "decision": "replace", "status": "CONFLICT", "reasoning": "Wikipedia (infobox type ''Kerb cairn'') and stone-circles.org.uk both say Little Meg''s ring of stones is the kerb of a Bronze Age burial cairn over a cist with an urned cremation, not a true stone circle, so Cairn is the most specific type.", "value_page": null}]'::jsonb),
