    ('71e7014b-7bc3-4c1b-9f10-884e4805c6e8'::uuid, 'site_type', 'Megalithic structures', 'Bath', 'fields-wd1-2026-09-26b-s005:71e7014b-7bc3-4c1b-9f10-884e4805c6e8:site_type', 'fields-wd1-2026-09-26b-s005 (wd1-replace): ''Megalithic structures'' -> ''Bath''', '[{"source": "http://odysseus.culture.gr/h/2/eh251.jsp?obj_id=5077", "url": "http://odysseus.culture.gr/h/2/eh251.jsp?obj_id=5077", "quote": "This is one of the most complete examples of an ancient gymnasium complex, which included the gymnasium proper, a palaestra and baths.", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Gymnasium_at_Delphi", "url": "https://en.wikipedia.org/wiki/Gymnasium_at_Delphi", "quote": "which comprised the xystus and the palaestra, along with its auxiliary buildings such as the changing rooms and baths", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0065)", "decision": "replace", "status": "CONFLICT", "reasoning": "The site is a 4th-century BC gymnasium complex (xystos, palaestra, circular cold pool with ten basins, Roman hot baths), not a megalithic structure. The canonical list has no gymnasium type; of the types that fit a gymnasium, Bath is the one both the Ministry of Culture and Wikipedia name as part of this complex.", "value_page": null}]'::jsonb),
    ('71f6f6f1-0cc8-4e43-9f9f-89ae7a635ffa'::uuid, 'site_type', 'Cemetery', 'Tomb', 'fields-wd1-2026-09-26b-s005:71f6f6f1-0cc8-4e43-9f9f-89ae7a635ffa:site_type', 'fields-wd1-2026-09-26b-s005 (wd1-replace): ''Cemetery'' -> ''Tomb''', '[{"source": "https://en.wikipedia.org/wiki/Phylaki", "url": "https://en.wikipedia.org/wiki/Phylaki", "quote": "The site, discovered in 1981, is a Late Minoan IIIA tholos tomb.", "outcome": "found"}, {"source": "https://topostext.org/place/353243XFyl", "url": "https://topostext.org/place/353243XFyl", "quote": "Mycenaean tholos tomb NW of Fylaki, Chania, Crete", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=63692", "url": "https://www.megalithic.co.uk/article.php?sid=63692", "quote": "Excavated in 1981, the tholos tomb of Phylaki is dated to Late Minoan III A-B period (14th-15th c. BC).", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0070)", "decision": "replace", "status": "CONFLICT", "reasoning": "Every source describes the site as a single Late Minoan tholos (beehive) tomb, not a cemetery, so the specific type is Tomb.", "value_page": null}]'::jsonb),
    ('7240c7dc-cd45-45f3-a291-7db1f48ce667'::uuid, 'period_name', '1000 - 1500 AD', NULL, 'fields-wd1-2026-09-26b-s005:7240c7dc-cd45-45f3-a291-7db1f48ce667:period_name', 'fields-wd1-2026-09-26b-s005 (wd1-derive-period-name): period_start None (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('7240c7dc-cd45-45f3-a291-7db1f48ce667'::uuid, 'period_start', '1000', NULL, 'fields-wd1-2026-09-26b-s005:7240c7dc-cd45-45f3-a291-7db1f48ce667:period_start', 'fields-wd1-2026-09-26b-s005 (wd1-clear): ''1000'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0113)", "decision": "clear", "status": "MISSING", "reasoning": "Wikipedia and the MINCETUR inventory date Qhapaq Kancha only to the Inca period (''of the Inca period'', ''perteneciente a la época inca'') without a year or century, so no quotable start year exists for the stored 1000.", "value_page": null}]'::jsonb),
    ('7240c7dc-cd45-45f3-a291-7db1f48ce667'::uuid, 'site_type', 'City/town/settlement', 'Archaeological site', 'fields-wd1-2026-09-26b-s005:7240c7dc-cd45-45f3-a291-7db1f48ce667:site_type', 'fields-wd1-2026-09-26b-s005 (wd1-replace): ''City/town/settlement'' -> ''Archaeological site''', '[{"source": "https://en.wikipedia.org/wiki/Qhapaq_Kancha", "url": "https://en.wikipedia.org/wiki/Qhapaq_Kancha", "quote": "is an archaeological site in Peru of the Inca period on top of a mountain of the same name.", "outcome": "found"}, {"source": "https://www.turismoperuano.com/sitio-arqueologico-ccapac-cancha-cusco", "url": "https://www.turismoperuano.com/sitio-arqueologico-ccapac-cancha-cusco", "quote": "Dichas construcciones están asentadas en una explanada en la cima del cerro Ccapac Cancha, perteneciente a la época inca.", "outcome": "found"}, {"source": "https://alicia.concytec.gob.pe/vufind/Record/RUNS_320eb35ff4f2511f9b6621152b783ad1/Description", "url": "https://alicia.concytec.gob.pe/vufind/Record/RUNS_320eb35ff4f2511f9b6621152b783ad1/Description", "quote": "El presente estudio describe características arquitectónicas en la zona arqueológica de Qhapaq Kancha", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0113)", "decision": "replace", "status": "MISSING", "reasoning": "Wikipedia, the MINCETUR inventory and a 2024 UNSAAC architectural survey describe an Inca-period summit complex (a plaza, three niched halls, streets, 72 structures including funerary ones, terraces) without calling it a town or settlement; with no specific type attested by two sources, the generic type holds.", "value_page": null}]'::jsonb),
    ('7268effd-38c0-4961-a203-561e19982b1f'::uuid, 'period_name', '1 - 500 AD', NULL, 'fields-wd1-2026-09-26b-s005:7268effd-38c0-4961-a203-561e19982b1f:period_name', 'fields-wd1-2026-09-26b-s005 (wd1-derive-period-name): period_start None (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('7268effd-38c0-4961-a203-561e19982b1f'::uuid, 'period_start', '1', NULL, 'fields-wd1-2026-09-26b-s005:7268effd-38c0-4961-a203-561e19982b1f:period_start', 'fields-wd1-2026-09-26b-s005 (wd1-clear): ''1'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0115)", "decision": "clear", "status": "MISSING", "reasoning": "No source (Wikipedia, the Chavín de Huántar municipal inventory, or any register) dates the Huaracayoc site, and nothing supports the stored 1 AD, so the field is emptied.", "value_page": null}]'::jsonb),
    ('7268effd-38c0-4961-a203-561e19982b1f'::uuid, 'site_type', 'City/town/settlement', 'Archaeological site', 'fields-wd1-2026-09-26b-s005:7268effd-38c0-4961-a203-561e19982b1f:site_type', 'fields-wd1-2026-09-26b-s005 (wd1-replace): ''City/town/settlement'' -> ''Archaeological site''', '[{"source": "https://en.wikipedia.org/wiki/Waraqayuq", "url": "https://en.wikipedia.org/wiki/Waraqayuq", "quote": "The archaeological site of Waraqayuq lies on the northern slope of the mountain at", "outcome": "found"}, {"source": "https://munichavindehuantar.gob.pe/wp-content/uploads/2024/10/Recursos-Turisticos.pdf", "url": "https://munichavindehuantar.gob.pe/wp-content/uploads/2024/10/Recursos-Turisticos.pdf", "quote": "Sitio Arqueológico Huaracayoc", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0115)", "decision": "replace", "status": "CONFLICT", "reasoning": "Wikipedia and the Chavín de Huántar district''s inventory of tourism resources both describe it only as an archaeological site (Sitio Arqueológico Huaracayoc, at Jircahuayi, 4320 m). No source calls it a town or settlement, so the stored City/town/settlement is replaced by the generic type.", "value_page": null}]'::jsonb),
    ('7279cb69-c5d2-4b9b-b307-96ef43164e7f'::uuid, 'period_name', '3000 - 1500 BC', NULL, 'fields-wd1-2026-09-26b-s005:7279cb69-c5d2-4b9b-b307-96ef43164e7f:period_name', 'fields-wd1-2026-09-26b-s005 (wd1-derive-period-name): period_start None (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('7279cb69-c5d2-4b9b-b307-96ef43164e7f'::uuid, 'period_start', '-3000', NULL, 'fields-wd1-2026-09-26b-s005:7279cb69-c5d2-4b9b-b307-96ef43164e7f:period_start', 'fields-wd1-2026-09-26b-s005 (wd1-clear): ''-3000'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0122)", "decision": "clear", "status": "MISSING", "reasoning": "Only the Ness of Brodgar Project states a date (the excavators'' late Neolithic c3000-2500BC); the BBC and German Wikipedia give only ''over 5,000 years'' and the bones could not be radiocarbon dated, so there are no two independent dated sources and the field is emptied.", "value_page": null}]'::jsonb),
    ('7279cb69-c5d2-4b9b-b307-96ef43164e7f'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/History', 'https://de.wikipedia.org/wiki/Crantit_Cairn', 'fields-wd1-2026-09-26b-s005:7279cb69-c5d2-4b9b-b307-96ef43164e7f:source_url', 'fields-wd1-2026-09-26b-s005 (wd1-replace): ''https://en.wikipedia.org/wiki/History'' -> ''https://de.wikipedia.org/wiki/Crantit_Cairn''', '[{"source": "https://de.wikipedia.org/wiki/Crantit_Cairn", "url": "https://de.wikipedia.org/wiki/Crantit_Cairn", "quote": "Die Ausgrabung des Crantit Cairn (gelegentlich als Crantit Souterrain bezeichnet), bei St. Ola, südlich von Kirkwall auf der Orkneyinsel Mainland in Schottland erfolgte unmittelbar nach der Entdeckung im Jahre 1998.", "outcome": "found"}, {"source": "https://www.nessofbrodgar.co.uk/crantit-chambered-cairn/", "url": "https://www.nessofbrodgar.co.uk/crantit-chambered-cairn/", "quote": "The Crantit chamber had lain undisturbed since it was sealed, so hopes were high that it would contain the untouched remains of early Orcadians.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0122)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored English article History is unrelated; the tomb''s own Wikipedia article is the German Crantit Cairn (sitelink of the site''s item Q1138920), about the chamber found in 1998 south of Kirkwall, which the Ness of Brodgar Project''s page describes as the same Crantit chamber.", "value_page": {"lang": "de", "problem": null, "resolved_title": "Crantit Cairn", "unreadable": false, "wikibase_item": "Q1138920"}}]'::jsonb),
    ('72b1b9e1-8e84-402b-b1bd-a7161527bca5'::uuid, 'period_name', '1 - 500 AD', NULL, 'fields-wd1-2026-09-26b-s005:72b1b9e1-8e84-402b-b1bd-a7161527bca5:period_name', 'fields-wd1-2026-09-26b-s005 (wd1-derive-period-name): period_start None (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('72b1b9e1-8e84-402b-b1bd-a7161527bca5'::uuid, 'period_start', '1', NULL, 'fields-wd1-2026-09-26b-s005:72b1b9e1-8e84-402b-b1bd-a7161527bca5:period_start', 'fields-wd1-2026-09-26b-s005 (wd1-clear): ''1'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0113)", "decision": "clear", "status": "MISSING", "reasoning": "No source dates the site by year or century: the Spanish Wikipedia list of Huancavelica''s archaeological monuments assigns Pirguayocc (Laria) only to the Late Intermediate Period, which also contradicts the stored AD 1.", "value_page": null}]'::jsonb),
    ('72b1b9e1-8e84-402b-b1bd-a7161527bca5'::uuid, 'site_type', 'City/town/settlement', 'Archaeological site', 'fields-wd1-2026-09-26b-s005:72b1b9e1-8e84-402b-b1bd-a7161527bca5:site_type', 'fields-wd1-2026-09-26b-s005 (wd1-replace): ''City/town/settlement'' -> ''Archaeological site''', '[{"source": "https://en.wikipedia.org/wiki/Pirwayuq", "url": "https://en.wikipedia.org/wiki/Pirwayuq", "quote": "is an archaeological site in Peru", "outcome": "found"}, {"source": "https://www.turismoperuano.com/restos-arqueologicos-de-pirwayoq-huancavelica", "url": "https://www.turismoperuano.com/restos-arqueologicos-de-pirwayoq-huancavelica", "quote": "El Resto arqueológico ocupa aprox. dos hectáreas en la cumbre del cerro llamado Pirwayoq.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0113)", "decision": "replace", "status": "CONFLICT", "reasoning": "Wikipedia calls Pirwayuq an archaeological site and the MINCETUR inventory text an archaeological remains of about two hectares on the summit of Cerro Pirwayoq with groups of circular dwellings (while classing it under ''Templos''); only one source describes it as a settlement, so the generic type is the one two sources support.", "value_page": null}]'::jsonb),
    ('72fc10c1-c363-4476-a9fe-56ddfdfc8cc2'::uuid, 'site_type', 'Temple complex', 'Sanctuary', 'fields-wd1-2026-09-26b-s005:72fc10c1-c363-4476-a9fe-56ddfdfc8cc2:site_type', 'fields-wd1-2026-09-26b-s005 (wd1-replace): ''Temple complex'' -> ''Sanctuary''', '[{"source": "https://www.sia.gr/en/articles.php?tid=329", "url": "https://www.sia.gr/en/articles.php?tid=329", "quote": "The Sanctuary of Poseidon on Kalaureia is located on the island of Poros in the Saronic Gulf, c. 6 km from Poros town.", "outcome": "found"}, {"source": "https://de.wikipedia.org/wiki/Poseidon-Heiligtum_von_Kalaureia", "url": "https://de.wikipedia.org/wiki/Poseidon-Heiligtum_von_Kalaureia", "quote": "war das zentrale Heiligtum der Amphiktyonie von Kalaureia.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0066)", "decision": "replace", "status": "CONFLICT", "reasoning": "The excavators and the site''s own Wikipedia article call it the Sanctuary of Poseidon, a temenos with a temple, stoas and a propylon; Sanctuary is the type they name.", "value_page": null}]'::jsonb),
    ('72fc10c1-c363-4476-a9fe-56ddfdfc8cc2'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Kalaureia', 'https://de.wikipedia.org/wiki/Poseidon-Heiligtum_von_Kalaureia', 'fields-wd1-2026-09-26b-s005:72fc10c1-c363-4476-a9fe-56ddfdfc8cc2:source_url', 'fields-wd1-2026-09-26b-s005 (wd1-replace): ''https://en.wikipedia.org/wiki/Kalaureia'' -> ''https://de.wikipedia.org/wiki/Poseidon-Heiligtum_von_Kalaureia''', '[{"source": "https://de.wikipedia.org/wiki/Poseidon-Heiligtum_von_Kalaureia", "url": "https://de.wikipedia.org/wiki/Poseidon-Heiligtum_von_Kalaureia", "quote": "Die archäologische Stätte des Poseidon-Heiligtums von Kalaureia liegt auf dem etwa 190 m hohen Plateau Palatia", "outcome": "found"}, {"source": "https://www.sia.gr/en/articles.php?tid=329", "url": "https://www.sia.gr/en/articles.php?tid=329", "quote": "The Sanctuary of Poseidon on Kalaureia is located on the island of Poros in the Saronic Gulf, c. 6 km from Poros town.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0066)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored English article is the island''s (Kalaureia, part of Poros); German Wikipedia has an article on the Poseidon sanctuary itself.", "value_page": {"lang": "de", "problem": null, "resolved_title": "Poseidon-Heiligtum von Kalaureia", "unreadable": false, "wikibase_item": "Q38281326"}}]'::jsonb),
