    ('73228e20-288b-42a1-9bbf-bcad94fecbbc'::uuid, 'period_name', '1500 - 500 BC', NULL, 'fields-wd1-2026-09-26b-s005:73228e20-288b-42a1-9bbf-bcad94fecbbc:period_name', 'fields-wd1-2026-09-26b-s005 (wd1-derive-period-name): period_start None (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('73228e20-288b-42a1-9bbf-bcad94fecbbc'::uuid, 'period_start', '-1500', NULL, 'fields-wd1-2026-09-26b-s005:73228e20-288b-42a1-9bbf-bcad94fecbbc:period_start', 'fields-wd1-2026-09-26b-s005 (wd1-clear): ''-1500'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0050)", "decision": "clear", "status": "MISSING", "reasoning": "Wikipedia states it is not known when the hillfort was built (only that it was destroyed in the 13th century) and the heritage register dates it only as Iron Age; no two sources give a year or century for its start, so the stored -1500 is emptied.", "value_page": null}]'::jsonb),
    ('7345ac3a-0fbd-4507-807b-a2f8a592c39d'::uuid, 'site_type', 'Megalithic structures', 'Funerary', 'fields-wd1-2026-09-26b-s005:7345ac3a-0fbd-4507-807b-a2f8a592c39d:site_type', 'fields-wd1-2026-09-26b-s005 (wd1-replace): ''Megalithic structures'' -> ''Funerary''', '[{"source": "https://chrisnaunton.com/the-osireion-links-further-reading/", "url": "https://chrisnaunton.com/the-osireion-links-further-reading/", "quote": "the decoration resembling texts and images from tombs in the Valley of Kings in an entrance corridor have led to the conclusion that it is a funerary monument although not a tomb – perhaps a cenotaph.", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Osireion", "url": "https://en.wikipedia.org/wiki/Osireion", "quote": "The Osireion (or Osirion) is believed to be the cenotaph of Seti I, located to the rear of the Temple of Seti I at Abydos, Egypt.", "outcome": "found"}, {"source": "https://madainproject.com/osireion", "url": "https://madainproject.com/osireion", "quote": "It is an integral part of Seti I''s funeral complex and is possibly built to resemble an 18th Dynasty Valley of the Kings tomb.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0023)", "decision": "replace", "status": "CONFLICT", "reasoning": "Egyptologist Chris Naunton calls the Osireion a funerary monument, perhaps a cenotaph; Wikipedia calls it the cenotaph of Seti I and the Madain Project part of Seti I''s funeral complex. Its megalithic blocks describe how it was built, not what it is, and it is not a temple in its own right, so the most specific canonical type is Funerary.", "value_page": null}]'::jsonb),
    ('7356fc90-8d0c-4554-b51d-f6b65c926244'::uuid, 'site_type', 'Rock art', 'Petroglyphs', 'fields-wd1-2026-09-26b-s005:7356fc90-8d0c-4554-b51d-f6b65c926244:site_type', 'fields-wd1-2026-09-26b-s005 (wd1-replace): ''Rock art'' -> ''Petroglyphs''', '[{"source": "https://en.wikipedia.org/wiki/Burrup_Peninsula", "url": "https://en.wikipedia.org/wiki/Burrup_Peninsula", "quote": "The Murujuga Cultural Landscape contains the world''s largest and most important collection of petroglyphs", "outcome": "found"}, {"source": "https://www.fara.com.au/about-murujuga", "url": "https://www.fara.com.au/about-murujuga", "quote": "Murujuga, or the Burrup Peninsula, is a unique ecological, spiritual and archaeological area, containing the world’s oldest, largest and most significant collection of petroglyphs/ancient rock carvings", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0006)", "decision": "replace", "status": "CONFLICT", "reasoning": "Wikipedia and the Friends of Australian Rock Art describe Murujuga''s rock art as a collection of petroglyphs (rock engravings), so the more specific Petroglyphs holds over the generic Rock art.", "value_page": null}]'::jsonb),
    ('7356fc90-8d0c-4554-b51d-f6b65c926244'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Murujuga', 'https://en.wikipedia.org/wiki/Burrup_Peninsula', 'fields-wd1-2026-09-26b-s005:7356fc90-8d0c-4554-b51d-f6b65c926244:source_url', 'fields-wd1-2026-09-26b-s005 (wd1-replace): ''https://en.wikipedia.org/wiki/Murujuga'' -> ''https://en.wikipedia.org/wiki/Burrup_Peninsula''', '[{"source": "https://en.wikipedia.org/wiki/Burrup_Peninsula", "url": "https://en.wikipedia.org/wiki/Burrup_Peninsula", "quote": "The peninsula includes the Murujuga Cultural Landscape, an area designated as a World Heritage Site in July 2025.", "outcome": "found"}, {"source": "https://www.fara.com.au/about-murujuga", "url": "https://www.fara.com.au/about-murujuga", "quote": "Murujuga, or the Burrup Peninsula, is a unique ecological, spiritual and archaeological area, containing the world’s oldest, largest and most significant collection of petroglyphs/ancient rock carvings", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0006)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored URL is a redirect; its target, the English Wikipedia article of the Murujuga item (Burrup Peninsula), carries the Murujuga Cultural Landscape World Heritage section and its rock art, and FARA confirms Murujuga is the Burrup Peninsula, so the article''s own URL replaces the redirect.", "value_page": {"lang": "en", "problem": null, "resolved_title": "Burrup Peninsula", "unreadable": false, "wikibase_item": "Q269163"}}]'::jsonb),
