    ('73be8eb3-140a-4646-8bfa-e7ec9d78c38c'::uuid, 'period_name', '4500 - 3000 BC', NULL, 'fields-wd1-2026-09-26b-s005:73be8eb3-140a-4646-8bfa-e7ec9d78c38c:period_name', 'fields-wd1-2026-09-26b-s005 (wd1-derive-period-name): period_start None (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('73be8eb3-140a-4646-8bfa-e7ec9d78c38c'::uuid, 'period_start', '-4000', NULL, 'fields-wd1-2026-09-26b-s005:73be8eb3-140a-4646-8bfa-e7ec9d78c38c:period_start', 'fields-wd1-2026-09-26b-s005 (wd1-clear): ''-4000'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0132)", "decision": "clear", "status": "MISSING", "reasoning": "Spanish Wikipedia and the Casabermeja tourism page assign the schematic paintings to the late Neolithic or Chalcolithic, and Wikipedia says their chronology is the hardest question to settle. No two independent sources give a year, century or millennium for when the site begins, so the stored 4000 BC cannot be confirmed and the field is emptied.", "value_page": null}]'::jsonb),
    ('73be8eb3-140a-4646-8bfa-e7ec9d78c38c'::uuid, 'site_type', 'Cave Structures', 'Rock art', 'fields-wd1-2026-09-26b-s005:73be8eb3-140a-4646-8bfa-e7ec9d78c38c:site_type', 'fields-wd1-2026-09-26b-s005 (wd1-replace): ''Cave Structures'' -> ''Rock art''', '[{"source": "https://en.wikipedia.org/wiki/Pe%C3%B1as_de_Cabrera", "url": "https://en.wikipedia.org/wiki/Pe%C3%B1as_de_Cabrera", "quote": "The entire complex of mountains and valleys consists of many shelters revealing rock art of paintings and engravings.", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=45872", "url": "https://www.megalithic.co.uk/article.php?sid=45872", "quote": "Type: Rock Art", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0132)", "decision": "replace", "status": "CONFLICT", "reasoning": "Wikipedia describes Peñas de Cabrera as open-air sandstone rock shelters with schematic rock paintings and engravings, and the Megalithic Portal lists it as a rock art site. The site is defined by its rock art, not by caves, so Rock art replaces Cave Structures.", "value_page": null}]'::jsonb),
    ('748bda90-84cd-452b-8cff-25d9185bab43'::uuid, 'site_type', 'Megalithic structures', 'Monument', 'fields-wd1-2026-09-26b-s005:748bda90-84cd-452b-8cff-25d9185bab43:site_type', 'fields-wd1-2026-09-26b-s005 (wd1-replace): ''Megalithic structures'' -> ''Monument''', '[{"source": "https://topostext.org/place/380237BSZe", "url": "https://topostext.org/place/380237BSZe", "quote": "The earliest monumental religious building in the Agora, built around 430 BCE.", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Stoa_of_Zeus_Eleutherios", "url": "https://en.wikipedia.org/wiki/Stoa_of_Zeus_Eleutherios", "quote": "was a two-aisled stoa located in the northwest corner of the", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0072)", "decision": "replace", "status": "CONFLICT", "reasoning": "The site is a single classical building, a two-aisled stoa of Zeus Eleutherios in the Athenian Agora, which ToposText calls a monumental religious building; nothing about it is megalithic, and no canonical type names a stoa, so Monument is the most specific fit.", "value_page": null}]'::jsonb),
    ('74af1ed2-4221-4e13-8a96-e63631d01cc7'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Phaselis', 'https://kulturenvanteri.com/yer/phaselis-buyuk-hamam/', 'fields-wd1-2026-09-26b-s005:74af1ed2-4221-4e13-8a96-e63631d01cc7:source_url', 'fields-wd1-2026-09-26b-s005 (wd1-replace): ''https://en.wikipedia.org/wiki/Phaselis'' -> ''https://kulturenvanteri.com/yer/phaselis-buyuk-hamam/''', '[{"source": "https://kulturenvanteri.com/yer/phaselis-buyuk-hamam/", "url": "https://kulturenvanteri.com/yer/phaselis-buyuk-hamam/", "quote": "Phaselis Büyük Hamam", "outcome": "found"}, {"source": "https://www.artichaeology.com/phaselis-ancient-city-turkey", "url": "https://www.artichaeology.com/phaselis-ancient-city-turkey", "quote": "Large bath called double-bath building AD III century A.D. and repaired on IV century AD.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0142)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored English Wikipedia article is about the city of Phaselis, not the bath; the Kulturenvanteri heritage inventory entry ''Phaselis Büyük Hamam'' (the item''s own identifier, type Hamam, Roman) is about this very building, which Artichaeology also describes as the large bath of Phaselis.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
    ('74c2c902-db56-411f-b98f-6711a6825b48'::uuid, 'source_url', 'http://ryanwunsch.com/mystery-rocks-saskatchewan/', 'https://bluejayjournal.ca/index.php/bluejay/article/view/5389', 'fields-wd1-2026-09-26b-s005:74c2c902-db56-411f-b98f-6711a6825b48:source_url', 'fields-wd1-2026-09-26b-s005 (wd1-replace): ''http://ryanwunsch.com/mystery-rocks-saskatchewan/'' -> ''https://bluejayjournal.ca/index.php/bluejay/article/view/5389''', '[{"source": "https://bluejayjournal.ca/index.php/bluejay/article/view/5389", "url": "https://bluejayjournal.ca/index.php/bluejay/article/view/5389", "quote": "“The Rock Pile,” Cypress Hills, Saskatchewan", "outcome": "found"}, {"source": "https://kitcho1.github.io/SaskInteractive98/Interactive/tourism/secrets/mystery.html", "url": "https://kitcho1.github.io/SaskInteractive98/Interactive/tourism/secrets/mystery.html", "quote": "A 45 minute hike from Fort Walsh in the Cypress Hills Interprovincial Park. This is private land and permission is required from the owner (ask at Fort Walsh).", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0015)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored blog post is dead (404); Rudy Klassen''s Blue Jay article on the Rock Pile near Fort Walsh, the local name of the Mystery Rocks, is a scholarly page about this very site, and the Saskatchewan Interactive page places the Mystery Rocks at the same spot near Fort Walsh.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
    ('74e0a41e-6437-4691-b430-35a076358628'::uuid, 'site_type', 'City/town/settlement', 'Temple complex', 'fields-wd1-2026-09-26b-s005:74e0a41e-6437-4691-b430-35a076358628:site_type', 'fields-wd1-2026-09-26b-s005 (wd1-replace): ''City/town/settlement'' -> ''Temple complex''', '[{"source": "https://en.wikipedia.org/wiki/Lydney_Park", "url": "https://en.wikipedia.org/wiki/Lydney_Park", "quote": "It is known for its gardens and Roman temple complex.", "outcome": "found"}, {"source": "https://www.roman-britain.co.uk/places/lydney_camp/", "url": "https://www.roman-britain.co.uk/places/lydney_camp/", "quote": "During the fourth-century the southern half of the site was taken over by a Romano-British temple complex. The religious buildings consisted of a substantial guest-house, a bath suite and a temple dedicated to Nodens", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0040)", "decision": "replace", "status": "CONFLICT", "reasoning": "The ancient site at Lydney Park is the Iron Age promontory fort overlain by the late Roman temple complex of Nodens (temple, guest-house, baths), not a town; both sources name the Roman temple complex as what the site is known for.", "value_page": null}]'::jsonb),
    ('74e4bdc2-675e-42b9-b390-898eabed0224'::uuid, 'period_name', '1500 - 500 BC', NULL, 'fields-wd1-2026-09-26b-s005:74e4bdc2-675e-42b9-b390-898eabed0224:period_name', 'fields-wd1-2026-09-26b-s005 (wd1-derive-period-name): period_start None (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('74e4bdc2-675e-42b9-b390-898eabed0224'::uuid, 'period_start', '-1000', NULL, 'fields-wd1-2026-09-26b-s005:74e4bdc2-675e-42b9-b390-898eabed0224:period_start', 'fields-wd1-2026-09-26b-s005 (wd1-clear): ''-1000'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0049)", "decision": "clear", "status": "MISSING", "reasoning": "No readable source dates the hillfort to around 1000 BC; the only dated construction statements (around 300 BC, from the Worlebury Hillfort Group and a blog paraphrasing it) come from one source family, and the group notes an earlier, undated smaller hillfort, so no two independent sources date the start and the field is emptied.", "value_page": null}]'::jsonb),
    ('74e4bdc2-675e-42b9-b390-898eabed0224'::uuid, 'site_type', 'Fortress/citadel', 'Fort', 'fields-wd1-2026-09-26b-s005:74e4bdc2-675e-42b9-b390-898eabed0224:site_type', 'fields-wd1-2026-09-26b-s005 (wd1-replace): ''Fortress/citadel'' -> ''Fort''', '[{"source": "https://en.wikipedia.org/wiki/Worlebury_Camp", "url": "https://en.wikipedia.org/wiki/Worlebury_Camp", "quote": "The fort was well defended with numerous walls, embankments and ditches around the site.", "outcome": "found"}, {"source": "https://n-somerset.gov.uk/my-services/libraries-leisure-open-spaces/parks-countryside/parks-open-spaces/worlebury-camp-hillfort", "url": "https://n-somerset.gov.uk/my-services/libraries-leisure-open-spaces/parks-countryside/parks-open-spaces/worlebury-camp-hillfort", "quote": "Worlebury Camp is an Iron Age hillfort that", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0049)", "decision": "replace", "status": "CONFLICT", "reasoning": "Wikipedia and North Somerset Council both describe the site as an Iron Age hillfort (Wikipedia: ''The fort was well defended''); the canonical type that holds a hillfort is Fort.", "value_page": null}]'::jsonb),
    ('74e4bdc2-675e-42b9-b390-898eabed0224'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Worlebury_Hill', 'https://en.wikipedia.org/wiki/Worlebury_Camp', 'fields-wd1-2026-09-26b-s005:74e4bdc2-675e-42b9-b390-898eabed0224:source_url', 'fields-wd1-2026-09-26b-s005 (wd1-replace): ''https://en.wikipedia.org/wiki/Worlebury_Hill'' -> ''https://en.wikipedia.org/wiki/Worlebury_Camp''', '[{"source": "https://en.wikipedia.org/wiki/Worlebury_Camp", "url": "https://en.wikipedia.org/wiki/Worlebury_Camp", "quote": "is the site of an Iron Age hillfort on Worlebury Hill", "outcome": "found"}, {"source": "https://n-somerset.gov.uk/my-services/libraries-leisure-open-spaces/parks-countryside/parks-open-spaces/worlebury-camp-hillfort", "url": "https://n-somerset.gov.uk/my-services/libraries-leisure-open-spaces/parks-countryside/parks-open-spaces/worlebury-camp-hillfort", "quote": "Worlebury Camp is an Iron Age hillfort that", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0049)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored article is about the hill; English Wikipedia has a dedicated article on the hillfort itself, Worlebury Camp, which the council page also names as the Iron Age hillfort at Worlebury Hill.", "value_page": {"lang": "en", "problem": null, "resolved_title": "Worlebury Camp", "unreadable": false, "wikibase_item": "Q8036819"}}]'::jsonb),
    ('74fe5dc2-1e2c-4dd6-b4ed-3cb376c9cd50'::uuid, 'site_type', 'Fortress/citadel', 'Fort', 'fields-wd1-2026-09-26b-s005:74fe5dc2-1e2c-4dd6-b4ed-3cb376c9cd50:site_type', 'fields-wd1-2026-09-26b-s005 (wd1-replace): ''Fortress/citadel'' -> ''Fort''', '[{"source": "https://en.wikipedia.org/wiki/Aballava", "url": "https://en.wikipedia.org/wiki/Aballava", "quote": "was a Roman fort on Hadrian''s Wall", "outcome": "found"}, {"source": "https://www.roman-britain.co.uk/places/aballava/", "url": "https://www.roman-britain.co.uk/places/aballava/", "quote": "The main fort Aballava is the Late-Hadrianic Wall Fort.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0025)", "decision": "replace", "status": "CONFLICT", "reasoning": "Both Wikipedia and Roman Britain describe Aballava as a Roman auxiliary fort on Hadrian''s Wall. Fort is the specific canonical type; it was not a fortress or citadel, and the ''human settlement'' class on Wikidata only reflects its vicus and the modern village.", "value_page": null}]'::jsonb),
    ('75374382-c6a7-4fb5-b9fb-cb1cd29fd7f2'::uuid, 'site_type', 'Ruin', 'Monument', 'fields-wd1-2026-09-26b-s005:75374382-c6a7-4fb5-b9fb-cb1cd29fd7f2:site_type', 'fields-wd1-2026-09-26b-s005 (wd1-replace): ''Ruin'' -> ''Monument''', '[{"source": "https://es.wikipedia.org/wiki/Estoa_de_Eumenes", "url": "https://es.wikipedia.org/wiki/Estoa_de_Eumenes", "quote": "algunos materiales de este monumento se usaron en la puerta Beulé", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Stoa_of_Eumenes", "url": "https://en.wikipedia.org/wiki/Stoa_of_Eumenes", "quote": "was a Hellenistic colonnade built on the South slope of the", "outcome": "found"}, {"source": "http://odysseus.culture.gr/h/3/eh352.jsp?obj_id=2409", "url": "http://odysseus.culture.gr/h/3/eh352.jsp?obj_id=2409", "quote": "It was a two- storeyed stoa and was made of an island marble of the sort used for most of the buildings of Pergamon.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0072)", "decision": "replace", "status": "CONFLICT", "reasoning": "The site is a single public building, a two-storeyed Hellenistic stoa (colonnade) on the South Slope of the Acropolis (Greek Ministry of Culture, Wikipedia), which Spanish Wikipedia calls a monument; no canonical type names a stoa, and Monument is more specific than the generic Ruin.", "value_page": null}]'::jsonb),
    ('753a8b5b-669c-4062-b935-93e619291597'::uuid, 'period_name', '3000 - 1500 BC', NULL, 'fields-wd1-2026-09-26b-s005:753a8b5b-669c-4062-b935-93e619291597:period_name', 'fields-wd1-2026-09-26b-s005 (wd1-derive-period-name): period_start None (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('753a8b5b-669c-4062-b935-93e619291597'::uuid, 'period_start', '-2000', NULL, 'fields-wd1-2026-09-26b-s005:753a8b5b-669c-4062-b935-93e619291597:period_start', 'fields-wd1-2026-09-26b-s005 (wd1-clear): ''-2000'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0065)", "decision": "clear", "status": "MISSING", "reasoning": "No source dates the start of Gyrton securely: it is named in Homer''s Catalogue of Ships and by Thucydides for 431 BC, and Wikipedia says its walls were built ''possibly already in the Archaic Period'', but no two independent sources give a year or century for its beginning. Mycenaean occupation is only ''probably'' claimed for the Bakraina acropolis, whose identification as Gyrton is itself disputed. The stored 2000 BC has no support.", "value_page": null}]'::jsonb),
    ('758dd394-0b33-4f82-821d-5b6de5058afe'::uuid, 'period_name', '4500 - 3000 BC', '3000 - 1500 BC', 'fields-wd1-2026-09-26b-s005:758dd394-0b33-4f82-821d-5b6de5058afe:period_name', 'fields-wd1-2026-09-26b-s005 (wd1-derive-period-name): period_start -3000 (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-3000) = ''3000 - 1500 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('758dd394-0b33-4f82-821d-5b6de5058afe'::uuid, 'period_start', '-4500', '-3000', 'fields-wd1-2026-09-26b-s005:758dd394-0b33-4f82-821d-5b6de5058afe:period_start', 'fields-wd1-2026-09-26b-s005 (wd1-replace): ''-4500'' -> ''-3000''', '[{"source": "https://www.berksarch.co.uk/index.php/bluestones-and-white-bones-the-origins-of-the-people-buried-at-stonehenge/", "url": "https://www.berksarch.co.uk/index.php/bluestones-and-white-bones-the-origins-of-the-people-buried-at-stonehenge/", "quote": "Phase 1 – c. 3000-2750 BC, the bank and ditch was constructed together with the ring of 56 Aubrey Holes, which may already have contained bluestones;", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Aubrey_holes", "url": "https://en.wikipedia.org/wiki/Aubrey_holes", "quote": "Professor Parker Pearson said: \"It''s very exciting that we have evidence for stones right from its beginnings around 3000 BC. That''s almost 500 years earlier than anyone had thought.\"", "outcome": "found"}, {"source": "https://www.english-heritage.org.uk/visit/places/stonehenge/history-and-stories/history/", "url": "https://www.english-heritage.org.uk/visit/places/stonehenge/history-and-stories/history/", "quote": "the earliest known major event was the construction of a circular ditch with an inner and outer bank, built about 3000 BC.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0026)", "decision": "replace", "status": "MISSING", "reasoning": "The Aubrey Holes were dug with Stonehenge''s first bank and ditch, which English Heritage, the Berkshire Archaeological Society report and the Stonehenge Riverside Project (quoted on Wikipedia) date to about 3000 BC; that start lies in the 3000-1500 BC bucket, not the stored 4500-3000 BC one.", "value_page": null}]'::jsonb),
    ('758dd394-0b33-4f82-821d-5b6de5058afe'::uuid, 'site_type', 'Timber circle', 'Cemetery', 'fields-wd1-2026-09-26b-s005:758dd394-0b33-4f82-821d-5b6de5058afe:site_type', 'fields-wd1-2026-09-26b-s005 (wd1-replace): ''Timber circle'' -> ''Cemetery''', '[{"source": "https://en.wikipedia.org/wiki/Aubrey_holes", "url": "https://en.wikipedia.org/wiki/Aubrey_holes", "quote": "25 of the pits contained later cremation burials inserted into their upper fills along with long bone pins which may have secured leather or cloth bags used to hold the remains. Their presence makes Stonehenge Britain''s oldest cremation cemetery.", "outcome": "found"}, {"source": "https://www.english-heritage.org.uk/visit/places/stonehenge/history-and-stories/history/", "url": "https://www.english-heritage.org.uk/visit/places/stonehenge/history-and-stories/history/", "quote": "Within and around the Aubrey Holes, and also in the ditch, people buried cremations. About 64 cremations have been found, and perhaps as many as 150 individuals were originally buried at Stonehenge, making it the largest late Neolithic cemetery in the British Isles.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0026)", "decision": "replace", "status": "CONFLICT", "reasoning": "The Aubrey Holes are a ring of 56 pits whose original contents are disputed (English Heritage: long held to be timber posts, now possibly stones; the 2008 re-excavation argues for bluestones, too shallow for posts), so Timber circle is not established; what the sources agree on is that the holes held cremation burials, Britain''s oldest cremation cemetery (not a quarry, as Wikidata has it).", "value_page": null}]'::jsonb),
    ('75dac040-12f2-4c78-b989-33cd3f5f07a9'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Pyramid_of_Userkaf', 'https://de.wikipedia.org/wiki/Neferhetepes-Pyramide', 'fields-wd1-2026-09-26b-s005:75dac040-12f2-4c78-b989-33cd3f5f07a9:source_url', 'fields-wd1-2026-09-26b-s005 (wd1-replace): ''https://en.wikipedia.org/wiki/Pyramid_of_Userkaf'' -> ''https://de.wikipedia.org/wiki/Neferhetepes-Pyramide''', '[{"source": "https://de.wikipedia.org/wiki/Neferhetepes-Pyramide", "url": "https://de.wikipedia.org/wiki/Neferhetepes-Pyramide", "quote": "Die Neferhetepes-Pyramide oder auch Königinnenpyramide der Neferhetepes befindet sich in der Nähe des ägyptischen Sakkara.", "outcome": "found"}, {"source": "https://egyptphoto.ncf.ca/pyramid%20of%20neferhetepes.htm", "url": "https://egyptphoto.ncf.ca/pyramid%20of%20neferhetepes.htm", "quote": "The pyramid is located about 100m south of Userkaf''s pyramid. Neferhetepes was a queen of Userkaf and is one of the largest queen pyramids of the old kingdom.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0024)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored URL is the article on Userkaf''s own pyramid (another Wikidata item); the site''s own article is the German Wikipedia page on the Neferhetepes pyramid at Saqqara (Wikidata Q1974158 sitelink; there is no English article), and egyptphoto.ncf.ca describes the same queen''s pyramid south of Userkaf''s.", "value_page": {"lang": "de", "problem": null, "resolved_title": "Neferhetepes-Pyramide", "unreadable": false, "wikibase_item": "Q1974158"}}]'::jsonb),
    ('75dccc9d-fb68-40a9-aa2e-e58a47067580'::uuid, 'site_type', 'Temple complex', 'Cave Structures', 'fields-wd1-2026-09-26b-s005:75dccc9d-fb68-40a9-aa2e-e58a47067580:site_type', 'fields-wd1-2026-09-26b-s005 (wd1-replace): ''Temple complex'' -> ''Cave Structures''', '[{"source": "https://en.wikipedia.org/wiki/Elephanta_Caves", "url": "https://en.wikipedia.org/wiki/Elephanta_Caves", "quote": "There are five rock-cut caves on the western hill and a brick stupa on the eastern hill.", "outcome": "found"}, {"source": "https://ibhforum.org/elephanta-caves/", "url": "https://ibhforum.org/elephanta-caves/", "quote": "The rock-cut Elephanta Caves were constructed about the mid-5th to 6th centuries AD", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0078)", "decision": "replace", "status": "CONFLICT", "reasoning": "The sources describe Elephanta as a group of rock-cut caves (five Hindu cave temples and two Buddhist caves) hewn into the island''s basalt hills, which the canonical type Cave Structures names more precisely than Temple complex.", "value_page": null}]'::jsonb),
    ('75f8edbd-7b29-4e09-a72a-9dd5f03e5caf'::uuid, 'site_type', 'Megalithic structures', 'Temple', 'fields-wd1-2026-09-26b-s005:75f8edbd-7b29-4e09-a72a-9dd5f03e5caf:site_type', 'fields-wd1-2026-09-26b-s005 (wd1-replace): ''Megalithic structures'' -> ''Temple''', '[{"source": "https://perseus-aa.github.io/items/aa_171.html", "url": "https://perseus-aa.github.io/items/aa_171.html", "quote": "Temple-like building; in the southern half of the Sanctuary of Apollo", "outcome": "found"}, {"source": "https://el.wikipedia.org/wiki/%CE%98%CE%B7%CF%83%CE%B1%CF%85%CF%81%CF%8C%CF%82_%CF%84%CF%89%CE%BD_%CE%9C%CE%B5%CE%B3%CE%B1%CF%81%CE%AD%CF%89%CE%BD", "url": "https://el.wikipedia.org/wiki/%CE%98%CE%B7%CF%83%CE%B1%CF%85%CF%81%CF%8C%CF%82_%CF%84%CF%89%CE%BD_%CE%9C%CE%B5%CE%B3%CE%B1%CF%81%CE%AD%CF%89%CE%BD", "quote": "Δωρικό κτίριο σε μορφή ναού", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0067)", "decision": "replace", "status": "CONFLICT", "reasoning": "The Megarian Treasury is a small Doric treasury in the form of a temple, distyle in antis, that held Megara''s offerings in the sanctuary of Apollo. The Perseus catalogue calls it a ''Temple-like building'' and Greek Wikipedia a Doric building in the form of a temple. It is not megalithic; Temple is the closest specific canonical type.", "value_page": null}]'::jsonb),
    ('767b931c-d5d6-4da3-80fd-bdd8b72f8663'::uuid, 'site_type', 'City/town/settlement', 'Quarry', 'fields-wd1-2026-09-26b-s005:767b931c-d5d6-4da3-80fd-bdd8b72f8663:site_type', 'fields-wd1-2026-09-26b-s005 (wd1-replace): ''City/town/settlement'' -> ''Quarry''', '[{"source": "https://en.wikipedia.org/wiki/Ta%C5%A1majdan_Park", "url": "https://en.wikipedia.org/wiki/Ta%C5%A1majdan_Park", "quote": "Almost two millennia ago, Romans were extracting stone from the quarry located in the area for the building of Belgrade''s predecessor, Singidunum", "outcome": "found"}, {"source": "https://myheritageguide.com/en/object/tasmajdan-park/", "url": "https://myheritageguide.com/en/object/tasmajdan-park/", "quote": "Tašmajdan Park is a central city park, located in the area of an ancient quarry.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0127)", "decision": "replace", "status": "CONFLICT", "reasoning": "Both sources describe the ancient site at Tasmajdan as a Roman stone quarry, not a settlement, so the specific type is Quarry.", "value_page": null}]'::jsonb),
