    ('76cfc1e7-19cc-48fc-a64b-b47f1767640a'::uuid, 'period_start', '-2000', '-1400', 'fields-wd1-2026-09-26b-s005:76cfc1e7-19cc-48fc-a64b-b47f1767640a:period_start', 'fields-wd1-2026-09-26b-s005 (wd1-replace): ''-2000'' -> ''-1400''', '[{"source": "https://www.interkriti.org/crete/rethymnon/armenoi_necropolis.html", "url": "https://www.interkriti.org/crete/rethymnon/armenoi_necropolis.html", "quote": "A-B (c. 1400-1200 B.C.) cemetery", "outcome": "found"}, {"source": "https://hellorethymno.com/guide/armeni-necropolis", "url": "https://hellorethymno.com/guide/armeni-necropolis", "quote": "a single tholos tomb, dating mainly to roughly 1400 to 1200 BC", "outcome": "found"}, {"source": "WD1 decision (counted, round 1, wd1-r1-b0009)", "decision": "replace", "status": "MISSING", "reasoning": "Two independent guides to the Late Minoan cemetery of Armeni (Armenoi), 8 km south of Rethymno, Crete, date its chamber tombs and the one tholos tomb to about 1400-1200 BC (Late Minoan IIIA-B), so the cemetery begins c. 1400 BC, in the 1500 - 500 BC bucket and not in the stored -2000 (3000 - 1500 BC). Wikipedia dates the single tholos to Late Minoan IB (c. 1625-1470 BC), but minoancrete.com dates that tholos to LM II-IIIA1, so the older date is not securely attested and the c. 1400 BC start stands.", "value_page": null}]'::jsonb),
    ('76cfc1e7-19cc-48fc-a64b-b47f1767640a'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Armeni_(archaeological_site)', 'https://en.wikipedia.org/wiki/Armenoi_(archaeological_site)', 'fields-wd1-2026-09-26b-s005:76cfc1e7-19cc-48fc-a64b-b47f1767640a:source_url', 'fields-wd1-2026-09-26b-s005 (wd1-replace): ''https://en.wikipedia.org/wiki/Armeni_(archaeological_site)'' -> ''https://en.wikipedia.org/wiki/Armenoi_(archaeological_site)''', '[{"source": "https://en.wikipedia.org/wiki/Armenoi_(archaeological_site)", "url": "https://en.wikipedia.org/wiki/Armenoi_(archaeological_site)", "quote": "Armeni has been under excavation since 1969 by Dr. Yiannis Tzedakis; 232 chamber tombs and one", "outcome": "found"}, {"source": "http://www.minoancrete.com/armeni.htm", "url": "http://www.minoancrete.com/armeni.htm", "quote": "The Late Minoan III cemetery of Armeni is located 8 kilometres south of Rethymno on the road to Spili and Ayia Galini.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0061)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored URL ''Armeni_(archaeological_site)'' is a redirect; the article''s own URL is ''Armenoi (archaeological site)'', which is about this Late Minoan cemetery of Armeni (Armenoi) south of Rethymno, and Minoan Crete independently describes the same cemetery of Armeni.", "value_page": {"lang": "en", "problem": null, "resolved_title": "Armenoi (archaeological site)", "unreadable": false, "wikibase_item": "Q1573075"}}]'::jsonb),
