    ('76d31c3a-0d8f-4b12-9b6d-41321e40af50'::uuid, 'period_start', '-132', '201', 'fields-wd1-2026-09-26b-s005:76d31c3a-0d8f-4b12-9b6d-41321e40af50:period_start', 'fields-wd1-2026-09-26b-s005 (wd1-replace): ''-132'' -> ''201''', '[{"source": "https://de.wikipedia.org/wiki/Zitadelle_von_Urfa", "url": "https://de.wikipedia.org/wiki/Zitadelle_von_Urfa", "quote": "erster Bau 3. Jhd. n. Chr.", "outcome": "found"}, {"source": "https://de.wikipedia.org/wiki/Zitadelle_von_Urfa", "url": "https://de.wikipedia.org/wiki/Zitadelle_von_Urfa", "quote": "baute 201 Abgar VIII. an der Südwestecke des Mauerrings auf dem Burgberg einen Winterpalast.", "outcome": "found"}, {"source": "https://www.sanliurfa.bel.tr/lang/en/icerik/12/7/urfa-castle", "url": "https://www.sanliurfa.bel.tr/lang/en/icerik/12/7/urfa-castle", "quote": "The two columns with Corinthian capitals on the castle were built as monumental columns during the reign of 9th MANU of Edessa Karalı between 240-242 AD.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0142)", "decision": "replace", "status": "MISSING", "reasoning": "The earliest securely dated building on the castle hill is of the 3rd century AD: German Wikipedia gives the first construction as 3rd century AD (Abgar VIII''s winter palace of 201), and the Şanlıurfa municipality dates the two monumental columns, the oldest surviving remains, to AD 240-242; the stored 132 BC is only the founding of the Osroene kingdom, so the start becomes 201.", "value_page": null}]'::jsonb),
