    ('770a7347-7227-408d-97e0-cf0c02b57157'::uuid, 'site_type', 'Residence/villa/farmhouse', 'Settlement', 'fields-wd1-2026-09-26b-s005:770a7347-7227-408d-97e0-cf0c02b57157:site_type', 'fields-wd1-2026-09-26b-s005 (wd1-replace): ''Residence/villa/farmhouse'' -> ''Settlement''', '[{"source": "https://cadwpublic-api.azurewebsites.net/reports/sam/FullReport?lang=en&id=3280", "url": "https://cadwpublic-api.azurewebsites.net/reports/sam/FullReport?lang=en&id=3280", "quote": "The monument comprises the remains of an enclosed settlement, located in low-lying fields", "outcome": "found"}, {"source": "https://coflein.gov.uk/en/sites/95582", "url": "https://coflein.gov.uk/en/sites/95582", "quote": "Bryn Eryr, Settlement Enclosure", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0152)", "decision": "replace", "status": "CONFLICT", "reasoning": "Cadw (national scheduling record) and RCAHMW''s Coflein (national inventory) both classify Bryn Eryr as an enclosed settlement, an Iron Age and Romano-British farm settlement, not a residence, villa or farmhouse, so ''Settlement'' replaces the stored type.", "value_page": null}]'::jsonb),
    ('7726fc99-c992-490d-a1ee-85e4755975fe'::uuid, 'site_type', 'Fortress/citadel', 'Settlement', 'fields-wd1-2026-09-26b-s005:7726fc99-c992-490d-a1ee-85e4755975fe:site_type', 'fields-wd1-2026-09-26b-s005 (wd1-replace): ''Fortress/citadel'' -> ''Settlement''', '[{"source": "https://en.wikipedia.org/wiki/Heidetrank_Oppidum", "url": "https://en.wikipedia.org/wiki/Heidetrank_Oppidum", "quote": "The oppidum was surrounded by ramparts which encircled the settlement of opposite sides of a ravine called the Heidetrankthal.", "outcome": "found"}, {"source": "https://www.verein-keltenwelten.de/keltische-staetten/oberursel-das-heidetraenk-oppidum/", "url": "https://www.verein-keltenwelten.de/keltische-staetten/oberursel-das-heidetraenk-oppidum/", "quote": "Eine gewaltig große Siedlung der Kelten, umgeben von einer heute noch als Wall erkennbaren Befestigung", "outcome": "found"}, {"source": "https://denkmal.hessen.de/von-uns/publikationen/uebersicht-der-publikationen/band-4-das-heidetraenk-oppidum", "url": "https://denkmal.hessen.de/von-uns/publikationen/uebersicht-der-publikationen/band-4-das-heidetraenk-oppidum", "quote": "der größten befestigten Siedlung im Bundesland Hessen", "outcome": "found"}, {"source": "WD1 decision (counted, round 1, wd1-r1-b0008)", "decision": "replace", "status": "CONFLICT", "reasoning": "Wikipedia, the KeltenWelten association and the Hessian heritage office (Landesamt fuer Denkmalpflege) all describe the Heidetraenk Oppidum near Oberursel as a very large Celtic (fortified) settlement encircled by ramparts, not a fortress or citadel, so the canonical type is Settlement.", "value_page": null}]'::jsonb),
