    ('7759e372-b62e-424a-a726-d078a5a49e54'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Selinunte', 'https://it.wikipedia.org/wiki/Tempio_G_di_Selinunte', 'fields-wd1-2026-09-26b-s005:7759e372-b62e-424a-a726-d078a5a49e54:source_url', 'fields-wd1-2026-09-26b-s005 (wd1-replace): ''https://en.wikipedia.org/wiki/Selinunte'' -> ''https://it.wikipedia.org/wiki/Tempio_G_di_Selinunte''', '[{"source": "https://it.wikipedia.org/wiki/Tempio_G_di_Selinunte", "url": "https://it.wikipedia.org/wiki/Tempio_G_di_Selinunte", "quote": "Posto sulla collina orientale che accoglie i resti di alcuni dei templi dell''antica città greca, era probabilmente dedicato a Zeus", "outcome": "found"}, {"source": "https://www2.regione.sicilia.it/beniculturali/dirbenicult/bca/L_Parchi/parco_selinunte.html", "url": "https://www2.regione.sicilia.it/beniculturali/dirbenicult/bca/L_Parchi/parco_selinunte.html", "quote": "propendere per un’attribuzione a Zeus del colossale tempio", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0088)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored English article is about the whole city of Selinunte; the temple has no English article, but the Italian Wikipedia article ''Tempio G di Selinunte'' (Tempio G, o di Zeus) is about this very temple, so it replaces the city page.", "value_page": {"lang": "it", "problem": null, "resolved_title": "Tempio G di Selinunte", "unreadable": false, "wikibase_item": "Q3983187"}}]'::jsonb),
