    ('776629fa-7b09-4af3-ad4c-3de6dff22753'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Midsummer_Hill', 'https://heritagerecords.nationaltrust.org.uk/HBSMR/MonRecord.aspx?uid=MNA143221', 'fields-wd1-2026-09-26b-s005:776629fa-7b09-4af3-ad4c-3de6dff22753:source_url', 'fields-wd1-2026-09-26b-s005 (wd1-replace): ''https://en.wikipedia.org/wiki/Midsummer_Hill'' -> ''https://heritagerecords.nationaltrust.org.uk/HBSMR/MonRecord.aspx?uid=MNA143221''', '[{"source": "https://heritagerecords.nationaltrust.org.uk/HBSMR/MonRecord.aspx?uid=MNA143221", "url": "https://heritagerecords.nationaltrust.org.uk/HBSMR/MonRecord.aspx?uid=MNA143221", "quote": "Despite partial afforestation, excavation and the insertion of pathways, the hillfort known as Midsummer Hill Camp survives comparatively well with substantial earthworks and terracing.", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=4750", "url": "https://www.megalithic.co.uk/article.php?sid=4750", "quote": "Midsummer Hill has a steep slope to the west and a rampart running north south along the west side.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0041)", "decision": "replace", "status": "CONFLICT", "reasoning": "The English Wikipedia article is about the hill; the hillfort Midsummer Hill Camp has no Wikipedia article of its own (its Wikidata item has no sitelinks), so the National Trust heritage record of the scheduled hillfort is its own page, and the Megalithic Portal names the same hillfort.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
