    ('788f9236-c12f-4f94-9dc6-4f3a3d682626'::uuid, 'site_type', 'Cave Structures', 'Sanctuary', 'fields-wd1-2026-09-26b-s005:788f9236-c12f-4f94-9dc6-4f3a3d682626:site_type', 'fields-wd1-2026-09-26b-s005 (wd1-replace): ''Cave Structures'' -> ''Sanctuary''', '[{"source": "https://patrimonios.pt/en/santuario-de-panoias/", "url": "https://patrimonios.pt/en/santuario-de-panoias/", "quote": "The Sanctuary of Panóias is one of the most unique monuments of the Roman world in the Iberian Peninsula: an open-air worship space, carved directly into three large granite outcrops in Vale de Nogueiras", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Panoias_Sanctuary", "url": "https://en.wikipedia.org/wiki/Panoias_Sanctuary", "quote": "The sanctuary is an enclosure with three large rocks, where several cavities of various sizes were opened and access stairs were also built.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0119)", "decision": "replace", "status": "CONFLICT", "reasoning": "Patrimónios, Wikipedia and the national register (typology ''Santuário'') describe Panóias as an open-air Roman rock-cut sanctuary with ritual cavities and inscriptions, not a cave structure, so the type is Sanctuary.", "value_page": null}]'::jsonb),
