    ('7895564a-2414-4bd5-a9c7-61e611f9159a'::uuid, 'site_type', 'Archaeological site', 'Military', 'fields-wd1-2026-09-26b-s005:7895564a-2414-4bd5-a9c7-61e611f9159a:site_type', 'fields-wd1-2026-09-26b-s005 (wd1-replace): ''Archaeological site'' -> ''Military''', '[{"source": "https://en.wikipedia.org/wiki/Lees_Hall_Roman_Camp", "url": "https://en.wikipedia.org/wiki/Lees_Hall_Roman_Camp", "quote": "The camp is one of over 40 temporary Roman camps recorded near Hadrian''s Wall; they may have been marching camps, or were occupied by troops constructing the wall, or were used during military training.", "outcome": "found"}, {"source": "https://keystothepast.info/search-records/results-of-search/results-of-search-2/site-details/?PRN=N6475", "url": "https://keystothepast.info/search-records/results-of-search/results-of-search-2/site-details/?PRN=N6475", "quote": "A Roman temporary camp, generally as described above.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0039)", "decision": "replace", "status": "CONFLICT", "reasoning": "Wikipedia and the Northumberland HER (Keys to the Past) both describe Lees Hall as a Roman temporary camp, a military encampment of troops; it is neither a permanent fort nor a generic archaeological site, so Military is the most specific canonical type.", "value_page": null}]'::jsonb),
