    ('78c18ef3-5f91-4629-bfef-37b0f13b2bef'::uuid, 'site_type', 'Megalithic structures', 'Sacred site', 'fields-wd1-2026-09-26b-s005:78c18ef3-5f91-4629-bfef-37b0f13b2bef:site_type', 'fields-wd1-2026-09-26b-s005 (wd1-replace): ''Megalithic structures'' -> ''Sacred site''', '[{"source": "https://en.wikipedia.org/wiki/Altar_of_Athena_Polias", "url": "https://en.wikipedia.org/wiki/Altar_of_Athena_Polias", "quote": "The Altar of Athena Polias was an altar on the Acropolis of Athens dedicated to the goddess Athena", "outcome": "found"}, {"source": "https://fr.wikipedia.org/wiki/Autel_d%27Ath%C3%A9na", "url": "https://fr.wikipedia.org/wiki/Autel_d%27Ath%C3%A9na", "quote": "L''autel d''Athéna est à la fois un territoire sacré, lien entre les hommes et la déesse qui protège ceux qui s''y réfugient, et le lieu de sacrifices majeurs", "outcome": "found"}, {"source": "https://pleiades.stoa.org/places/521295193/json", "url": "https://pleiades.stoa.org/places/521295193/json", "quote": "The altar of Athena Polias on the Acropolis of Athens, built in or before the 7th century BC.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0060)", "decision": "replace", "status": "CONFLICT", "reasoning": "English Wikipedia and Pleiades both describe the site as the altar of Athena Polias on the Acropolis (Pleiades classes it as a shrine); French Wikipedia calls it a sacred territory and the place of the great sacrifices. It is an open-air cult altar, a sacred site; nothing megalithic is described, so ''Megalithic structures'' is replaced.", "value_page": null}]'::jsonb),
