    ('78dcb136-e26a-4653-b586-6b75dd96ccb4'::uuid, 'site_type', 'Temple complex', 'Sanctuary', 'fields-wd1-2026-09-26b-s005:78dcb136-e26a-4653-b586-6b75dd96ccb4:site_type', 'fields-wd1-2026-09-26b-s005 (wd1-replace): ''Temple complex'' -> ''Sanctuary''', '[{"source": "https://en.wikipedia.org/wiki/Mersinaki", "url": "https://en.wikipedia.org/wiki/Mersinaki", "quote": "excavated Mersinaki during the year 1930 and found an open-air sanctuary by a river delta.", "outcome": "found"}, {"source": "http://phrc.it/index.php?module=content&object=745", "url": "http://phrc.it/index.php?module=content&object=745", "quote": "The sanctuary at Mersinaki was in use between the archaic period", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0020)", "decision": "replace", "status": "MISSING", "reasoning": "Wikipedia and the PHRC database both describe Mersinaki as a sanctuary (an open-air temenos with few architectural remains, dedicated to Apollo and Athena), which is the canonical type Sanctuary rather than Temple complex.", "value_page": null}]'::jsonb),
    ('78f9ceea-623f-4224-9357-8790bc93e522'::uuid, 'period_name', '500 BC - 1 AD', '1500 - 500 BC', 'fields-wd1-2026-09-26b-s005:78f9ceea-623f-4224-9357-8790bc93e522:period_name', 'fields-wd1-2026-09-26b-s005 (wd1-derive-period-name): period_start -1000 (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-1000) = ''1500 - 500 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('78f9ceea-623f-4224-9357-8790bc93e522'::uuid, 'period_start', '-500', '-1000', 'fields-wd1-2026-09-26b-s005:78f9ceea-623f-4224-9357-8790bc93e522:period_start', 'fields-wd1-2026-09-26b-s005 (wd1-replace): ''-500'' -> ''-1000''', '[{"source": "https://en.wikipedia.org/wiki/Alexandria_Arachosia", "url": "https://en.wikipedia.org/wiki/Alexandria_Arachosia", "quote": "the terminus post quem for a settlement on the site is c. 1000 BC, but analysis of pottery favours a later date of c. 700 BC.", "outcome": "found"}, {"source": "https://www.barpublishing.com/book/excavationas-at-kandahar-1974-and-1975/", "url": "https://www.barpublishing.com/book/excavationas-at-kandahar-1974-and-1975/", "quote": "It has all major periods represented from the Iron Age in the 1st millennium BC to the Islamic conquest", "outcome": "found"}, {"source": "WD1 decision (counted, round 1, wd1-r1-b0001)", "decision": "replace", "status": "MISSING", "reasoning": "The excavations at Shahr-i Kohna (Old Kandahar), the tell of Alexandria in Arachosia, show a settlement from the Iron Age of the 1st millennium BC (Wikipedia: terminus post quem c. 1000 BC, pottery favouring c. 700 BC; the excavation volume: Iron Age in the 1st millennium BC), so the start lies in the 1500-500 BC bucket and not in 500 BC - 1 AD; Alexander''s foundation of about 330 BC refounded an existing Achaemenid town.", "value_page": null}]'::jsonb),
    ('78f9ceea-623f-4224-9357-8790bc93e522'::uuid, 'site_type', 'Fortress/citadel', 'City', 'fields-wd1-2026-09-26b-s005:78f9ceea-623f-4224-9357-8790bc93e522:site_type', 'fields-wd1-2026-09-26b-s005 (wd1-replace): ''Fortress/citadel'' -> ''City''', '[{"source": "https://en.wikipedia.org/wiki/Alexandria_Arachosia", "url": "https://en.wikipedia.org/wiki/Alexandria_Arachosia", "quote": "was a city in ancient times that is now called Kandahar in Afghanistan.", "outcome": "found"}, {"source": "https://www.livius.org/articles/place/alexandria-in-arachosia-kandahar/", "url": "https://www.livius.org/articles/place/alexandria-in-arachosia-kandahar/", "quote": "The city is identical to modern Kandahar, which still bears the ancient name", "outcome": "found"}, {"source": "https://www.barpublishing.com/book/excavationas-at-kandahar-1974-and-1975/", "url": "https://www.barpublishing.com/book/excavationas-at-kandahar-1974-and-1975/", "quote": "and is a city of major military and strategic significance, of more than purely local importance.", "outcome": "found"}, {"source": "WD1 decision (counted, round 1, wd1-r1-b0001)", "decision": "replace", "status": "CONFLICT", "reasoning": "Wikipedia, Livius and the excavation volume all describe Alexandria in Arachosia / Old Kandahar as an ancient city (with a citadel on its tell), not merely a fortress, so City is the most specific type that holds what the sources say.", "value_page": null}]'::jsonb),
    ('791b7bc8-8015-4715-ae40-50452a4c6fb5'::uuid, 'period_name', '1000 - 1500 AD', NULL, 'fields-wd1-2026-09-26b-s005:791b7bc8-8015-4715-ae40-50452a4c6fb5:period_name', 'fields-wd1-2026-09-26b-s005 (wd1-derive-period-name): period_start None (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('791b7bc8-8015-4715-ae40-50452a4c6fb5'::uuid, 'period_start', '1400', NULL, 'fields-wd1-2026-09-26b-s005:791b7bc8-8015-4715-ae40-50452a4c6fb5:period_start', 'fields-wd1-2026-09-26b-s005 (wd1-clear): ''1400'' -> None', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0012)", "decision": "clear", "status": "MISSING", "reasoning": "Only one source dates the site: Correo del Alba says the Inca bridge ''data del siglo XV''; Wikipedia and Los Tiempos only say ''época incaica'' without a year or century, so no two independent sources date the start.", "value_page": null}]'::jsonb),
    ('791b7bc8-8015-4715-ae40-50452a4c6fb5'::uuid, 'site_type', 'City/town/settlement', 'Bridge', 'fields-wd1-2026-09-26b-s005:791b7bc8-8015-4715-ae40-50452a4c6fb5:site_type', 'fields-wd1-2026-09-26b-s005 (wd1-replace): ''City/town/settlement'' -> ''Bridge''', '[{"source": "https://en.wikipedia.org/wiki/Inkachaka", "url": "https://en.wikipedia.org/wiki/Inkachaka", "quote": "Inkachaka or Inka Chaka (Quechua Inka Inca, chaka bridge,[1] \"Inca bridge\", hispanicized spellings Incachaca, Inca Chaca) is an archaeological site in Bolivia.", "outcome": "found"}, {"source": "https://www.lostiempos.com/actualidad/local/20170604/incachaca-destino-descubrir", "url": "https://www.lostiempos.com/actualidad/local/20170604/incachaca-destino-descubrir", "quote": "El Puente de los Incas o Incachaca es un sitio con un gran potencial turístico, ubicado en el camino al trópico de Cochabamba y a 80 kilómetros de la ciudad", "outcome": "found"}, {"source": "https://www.correodelalba.org/2024/09/13/la-antigua-ruta-de-los-incas/", "url": "https://www.correodelalba.org/2024/09/13/la-antigua-ruta-de-los-incas/", "quote": "El Puente del Inca, de uso exclusivo de los chasquis o mensajeros, data del siglo XV", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0012)", "decision": "replace", "status": "CONFLICT", "reasoning": "The site is named for and identified with its Inca bridge on the Inca road (Wikipedia ''Inca bridge''; Los Tiempos ''El Puente de los Incas o Incachaca''; Correo del Alba ''El Puente del Inca''); no source describes a city, town or settlement, so Bridge replaces City/town/settlement.", "value_page": null}]'::jsonb),
